window.QBANK = window.QBANK || {};
window.QBANK["smp-seni"] = {
  level: "SMP", subject: "Seni", duration: 900,
  questions: [
    { q: "Unsur seni rupa yang paling dasar dan menjadi awal terbentuknya garis adalah ....", options: ["Titik", "Bidang", "Tekstur", "Ruang"], answer: 0, solution: "1. Unsur seni rupa yang paling sederhana adalah titik. 2. Deretan titik yang saling terhubung akan membentuk garis. 3. Garis kemudian membentuk bidang, lalu bidang membentuk bentuk — jadi titik adalah awal dari semuanya." },
    { q: "Dalam menggambar perspektif, garis khayal tempat semua garis sejajar seolah-olah bertemu disebut ....", options: ["Garis vertikal", "Garis horizon", "Garis diagonal", "Garis kontur"], answer: 1, solution: "1. Perspektif meniru cara mata melihat: benda yang menjauh tampak mengecil. 2. Semua garis yang sejajar akan tampak bertemu pada satu garis khayal. 3. Garis khayal itu disebut garis horizon (garis cakrawala)." },
    { q: "Teknik menggambar dengan membuat titik-titik kecil untuk membentuk kesan gelap-terang disebut ....", options: ["Arsir", "Dusel", "Pointilis", "Aquarel"], answer: 2, solution: "1. Kesan gelap-terang bisa dibuat dengan titik-titik kecil yang rapat atau renggang. 2. Teknik ini disebut pointilis, dari kata point yang artinya titik. 3. Arsir memakai goresan garis, dusel memakai gosokan, aquarel adalah teknik cat air." },
    { q: "Prinsip seni rupa yang mengatur susunan objek agar gambar terlihat stabil dan tidak berat sebelah disebut ....", options: ["Irama (rhythm)", "Proporsi", "Kontras", "Keseimbangan (balance)"], answer: 3, solution: "1. Objek yang menumpuk di satu sisi membuat gambar terasa goyang atau berat sebelah. 2. Prinsip yang mengatur kestabilan susunan adalah keseimbangan (balance). 3. Keseimbangan bisa simetris (kiri-kanan sama) maupun asimetris (tetap seimbang meski tidak sama)." },
    { q: "Patung yang dibuat dari tanah liat atau plastisin dengan cara dipijat dan dibentuk memakai jari disebut teknik ....", options: ["Butsir", "Pahat", "Cor", "Ukir"], answer: 0, solution: "1. Tanah liat dan plastisin adalah bahan lunak yang mudah dibentuk. 2. Bahan lunak dibentuk dengan cara dipijat memakai jari atau alat butsir. 3. Teknik ini disebut butsir (modeling); pahat dan ukir dipakai untuk bahan keras seperti kayu dan batu." },
    { q: "Berikut ini yang termasuk prinsip seni rupa adalah ....", options: ["Garis", "Kesatuan (unity)", "Warna", "Tekstur"], answer: 1, solution: "1. Unsur seni rupa adalah bahan pembentuk karya: titik, garis, bidang, warna, tekstur, ruang. 2. Prinsip seni rupa adalah kaidah penyusunannya: kesatuan, keseimbangan, irama, penekanan, proporsi. 3. Jadi kesatuan termasuk prinsip, sedangkan garis, warna, dan tekstur adalah unsur." },
    { q: "Komposisi yang menempatkan objek utama tepat di tengah bidang gambar dengan sisi kiri dan kanan seimbang disebut komposisi ....", options: ["Asimetris", "Diagonal", "Simetris", "Acak"], answer: 2, solution: "1. Komposisi mengatur letak objek pada bidang gambar. 2. Objek utama di tengah dengan kiri-kanan seimbang disebut komposisi simetris. 3. Komposisi asimetris justru menempatkan objek tidak di tengah tetapi tetap seimbang." },
    { q: "Warna merah, kuning, dan biru dalam lingkaran warna disebut warna ....", options: ["Sekunder", "Tersier", "Komplementer", "Primer"], answer: 3, solution: "1. Ada warna pokok yang tidak dapat dibuat dari campuran warna lain. 2. Merah, kuning, dan biru adalah tiga warna pokok tersebut. 3. Warna pokok disebut warna primer; warna sekunder (hijau, oranye, ungu) adalah hasil campuran dua warna primer." },
    { q: "Teknik membuat patung dengan cara mengurangi bahan keras seperti kayu atau batu memakai pahat disebut ....", options: ["Memahat", "Mencetak", "Merakit", "Menyusun"], answer: 0, solution: "1. Kayu dan batu adalah bahan keras yang tidak bisa dipijat. 2. Bahan keras dibentuk dengan cara dikurangi atau dikikis memakai pahat. 3. Tekniknya disebut memahat; mencetak dipakai untuk bahan cair seperti logam atau gips." },
    { q: "Dalam perspektif satu titik hilang, benda yang digambar sejajar bidang gambar akan tampak ....", options: ["Membesar ke arah depan", "Menyusut ke arah titik hilang", "Tetap sama ukurannya", "Berputar miring"], answer: 1, solution: "1. Perspektif meniru pandangan mata: benda yang jauh tampak lebih kecil. 2. Garis-garis rusuk benda ditarik menuju satu titik hilang pada garis horizon. 3. Akibatnya benda tampak menyusut ke arah titik hilang tersebut." },
    { q: "Kesan irama (rhythm) dalam karya seni rupa diperoleh dengan cara ....", options: ["Memakai satu warna saja", "Menggambar objek berukuran besar", "Mengulang unsur secara teratur", "Menumpuk semua objek di tengah"], answer: 2, solution: "1. Irama adalah kesan gerak yang mengalir dan teratur dalam karya. 2. Cara menciptakannya adalah mengulang unsur seni rupa (garis, bentuk, warna) secara teratur. 3. Pengulangan inilah yang menimbulkan ritme visual, seperti ketukan dalam musik." },
    { q: "Alat yang dipakai untuk menghaluskan arsiran pensil sehingga menghasilkan gradasi lembut disebut ....", options: ["Kuas cat", "Pisau palet", "Penggaris", "Dusel (tortillon)"], answer: 3, solution: "1. Arsiran pensil yang kasar dapat dihaluskan dengan cara digosok. 2. Alat gosok berbentuk gulungan kertas yang runcing disebut dusel atau tortillon. 3. Kuas dipakai untuk cat, pisau palet untuk mencampur cat di atas palet." },
    { q: "Patung yang berfungsi memperindah ruangan atau bangunan dan bentuknya bebas tidak harus menyerupai makhluk hidup disebut patung ....", options: ["Dekoratif", "Religius", "Monumen", "Arsitektur"], answer: 0, solution: "1. Patung dibedakan menurut fungsinya. 2. Patung dekoratif berfungsi sebagai hiasan untuk memperindah ruangan atau bangunan. 3. Bentuknya bebas dan lebih menonjolkan keindahan bentuk, berbeda dengan patung monumen yang mengenang tokoh atau peristiwa." },
    { q: "Tekstur dalam karya seni rupa adalah ....", options: ["Ukuran besar kecilnya objek", "Kesan permukaan suatu benda, halus atau kasar", "Arah datangnya cahaya", "Jarak antar objek dalam gambar"], answer: 1, solution: "1. Setiap benda memiliki permukaan yang dapat diraba atau dilihat. 2. Kesan halus, kasar, licin, atau berpori pada permukaan itulah yang disebut tekstur. 3. Tekstur nyata dapat diraba langsung, sedangkan tekstur semu hanya tampak oleh mata." },
    { q: "Langkah pertama yang benar sebelum menggambar objek dengan teknik perspektif adalah ....", options: ["Mewarnai objek gambar", "Membuat detail terkecil objek", "Menentukan garis horizon dan titik hilang", "Menebalkan garis luar objek"], answer: 2, solution: "1. Gambar perspektif dibangun di atas kerangka garis khayal. 2. Tanpa garis horizon dan titik hilang, gambar tidak memiliki acuan kedalaman ruang. 3. Jadi tentukan dulu garis horizon dan titik hilang, barulah objek digambar di atasnya." },
    { q: "Pada notasi angka, nada 'do' dilambangkan dengan angka ....", options: ["2", "3", "7", "1"], answer: 3, solution: "1. Notasi angka memakai angka 1 sampai 7 untuk menuliskan nada. 2. Urutannya adalah 1 = do, 2 = re, 3 = mi, 4 = fa, 5 = sol, 6 = la, 7 = si. 3. Jadi nada 'do' dilambangkan dengan angka 1." },
    { q: "Garis paranada pada notasi balok terdiri atas ....", options: ["5 garis dan 4 spasi", "4 garis dan 5 spasi", "6 garis dan 5 spasi", "5 garis dan 5 spasi"], answer: 0, solution: "1. Notasi balok ditulis pada garis paranada (sangkar nada). 2. Paranada terdiri dari 5 garis horizontal yang sejajar. 3. Di antara kelima garis tersebut terdapat 4 spasi (ruang)." },
    { q: "Pola interval tangga nada mayor adalah ....", options: ["1 - 1/2 - 1 - 1 - 1/2 - 1 - 1", "1 - 1 - 1/2 - 1 - 1 - 1 - 1/2", "1/2 - 1 - 1 - 1 - 1 - 1 - 1/2", "1 - 1 - 1 - 1/2 - 1 - 1 - 1/2"], answer: 1, solution: "1. Tangga nada mayor memiliki pola jarak (interval) yang khas. 2. Jarak setengah (1/2) terletak di antara nada mi-fa dan si-do. 3. Polanya adalah 1 - 1 - 1/2 - 1 - 1 - 1 - 1/2." },
    { q: "Alat musik angklung berasal dari daerah ....", options: ["Jawa Tengah", "Sumatera Barat", "Jawa Barat", "Bali"], answer: 2, solution: "1. Angklung terbuat dari bambu dan dibunyikan dengan cara digoyangkan. 2. Angklung adalah alat musik khas masyarakat Sunda. 3. Masyarakat Sunda berada di Jawa Barat, jadi angklung berasal dari Jawa Barat." },
    { q: "Lagu daerah 'Ampar-ampar Pisang' berasal dari ....", options: ["Kalimantan Timur", "Sumatera Selatan", "Sulawesi Selatan", "Kalimantan Selatan"], answer: 3, solution: "1. Lagu Ampar-ampar Pisang dinyanyikan dalam bahasa Banjar. 2. Suku Banjar berasal dari Kalimantan Selatan. 3. Jadi lagu ini berasal dari Kalimantan Selatan, bukan Kalimantan Timur." },
    { q: "Lagu 'Yamko Rambe Yamko' berasal dari ....", options: ["Papua", "Maluku", "Nusa Tenggara Timur", "Sulawesi Utara"], answer: 0, solution: "1. Lagu Yamko Rambe Yamko dinyanyikan dalam bahasa daerah Papua. 2. Liriknya bercerita tentang bunga. 3. Jadi lagu ini berasal dari Papua — jangan tertukar dengan lagu Maluku seperti Burung Kakak Tua." },
    { q: "Alat musik sasando berasal dari ....", options: ["Nusa Tenggara Barat", "Nusa Tenggara Timur", "Maluku", "Papua"], answer: 1, solution: "1. Sasando adalah alat musik petik yang memiliki banyak dawai. 2. Sasando berasal dari Pulau Rote. 3. Pulau Rote termasuk wilayah provinsi Nusa Tenggara Timur." },
    { q: "Lagu 'Burung Kakak Tua' berasal dari ....", options: ["Papua", "Sulawesi Utara", "Maluku", "Nusa Tenggara Timur"], answer: 2, solution: "1. Lagu Burung Kakak Tua bercerita tentang burung kakak tua yang hinggap di jendela. 2. Lagu ini berasal dari Maluku. 3. Jangan tertukar dengan lagu Papua seperti Apuse atau Yamko Rambe Yamko." },
    { q: "Tanda tempo 'allegro' berarti lagu dimainkan dengan ....", options: ["Lambat dan sedih", "Sedang dan tenang", "Makin lama makin cepat", "Cepat dan riang"], answer: 3, solution: "1. Tempo mengatur cepat atau lambatnya sebuah lagu dimainkan. 2. Allegro adalah tanda tempo cepat yang bernuansa riang dan bersemangat. 3. Lawannya adalah adagio atau largo (lambat) dan andante (sedang)." },
    { q: "Alat musik kolintang berasal dari ....", options: ["Sulawesi Utara", "Sulawesi Selatan", "Sulawesi Tengah", "Sulawesi Tenggara"], answer: 0, solution: "1. Kolintang adalah alat musik pukul yang terbuat dari bilah-bilah kayu. 2. Kolintang berasal dari daerah Minahasa. 3. Minahasa berada di Sulawesi Utara." },
    { q: "Lagu 'Gundul-gundul Pacul' berasal dari ....", options: ["Jawa Barat", "Jawa Tengah", "Jawa Timur", "DI Yogyakarta"], answer: 1, solution: "1. Lagu Gundul-gundul Pacul dinyanyikan dalam bahasa Jawa. 2. Lagu dolanan anak ini berasal dari Jawa Tengah. 3. Jangan tertukar dengan lagu Sunda dari Jawa Barat seperti Manuk Dadali." },
    { q: "Gitar, biola, dan kecapi termasuk kelompok alat musik ....", options: ["Aerofon (sumber bunyi udara)", "Membranofon (sumber bunyi selaput kulit)", "Kordofon (sumber bunyi dawai)", "Idiofon (sumber bunyi badan alat)"], answer: 2, solution: "1. Alat musik dikelompokkan menurut sumber bunyinya. 2. Gitar, biola, dan kecapi berbunyi karena dawai atau senarnya dipetik dan digesek. 3. Kelompok alat musik yang sumber bunyinya dawai disebut kordofon." },
    { q: "Lagu 'Apuse' berasal dari ....", options: ["Maluku", "Nusa Tenggara Timur", "Sulawesi", "Papua"], answer: 3, solution: "1. Lagu Apuse dinyanyikan dalam bahasa Biak. 2. Bahasa Biak dipakai oleh masyarakat di Papua. 3. Jadi Apuse adalah lagu daerah Papua." },
    { q: "Alat musik tifa cara memainkannya adalah ....", options: ["Dipukul dengan tangan", "Ditiup", "Dipetik", "Digesek"], answer: 0, solution: "1. Tifa berbentuk tabung dengan selaput kulit pada salah satu ujungnya. 2. Alat musik yang sumber bunyinya selaput kulit (membranofon) dibunyikan dengan cara dipukul. 3. Tifa khas Maluku dan Papua dipukul memakai tangan." },
    { q: "Lagu 'Ayam Den Lapeh' berasal dari ....", options: ["Sumatera Utara", "Sumatera Barat", "Riau", "Jambi"], answer: 1, solution: "1. Lagu Ayam Den Lapeh dinyanyikan dalam bahasa Minangkabau. 2. Suku Minangkabau berasal dari Sumatera Barat. 3. Jadi lagu ini berasal dari Sumatera Barat, bukan Sumatera Utara." },
    { q: "Pada tangga nada C mayor, nada ke-5 yaitu 'sol' adalah ....", options: ["F", "A", "G", "E"], answer: 2, solution: "1. Tangga nada C mayor berurutan C - D - E - F - G - A - B - C. 2. Dalam solmisasi: do = C, re = D, mi = E, fa = F, sol = G. 3. Jadi nada ke-5 (sol) adalah G." },
    { q: "Alat musik modern berikut yang termasuk kelompok aerofon adalah ....", options: ["Drum", "Piano", "Gitar listrik", "Saksofon"], answer: 3, solution: "1. Aerofon adalah alat musik yang sumber bunyinya getaran udara yang ditiup. 2. Saksofon ditiup sehingga kolom udara di dalamnya bergetar menghasilkan bunyi. 3. Drum termasuk membranofon, sedangkan piano dan gitar termasuk kordofon." },
    { q: "Tari Saman berasal dari daerah ....", options: ["Aceh", "Sumatera Barat", "Sumatera Utara", "Riau"], answer: 0, solution: "1. Tari Saman ditarikan sambil duduk berbanjar dengan tepukan tangan dan dada yang kompak. 2. Tari ini berasal dari suku Gayo. 3. Suku Gayo berada di Aceh, jadi Tari Saman berasal dari Aceh." },
    { q: "Tari Kecak berasal dari daerah ....", options: ["Jawa Timur", "Bali", "Lombok", "Jawa Barat"], answer: 1, solution: "1. Tari Kecak diiringi suara 'cak-cak-cak' yang diteriakkan puluhan penari laki-laki. 2. Tari ini menceritakan kisah Ramayana. 3. Tari Kecak berasal dari Bali." },
    { q: "Gerak tari yang memiliki arti atau maksud tertentu, misalnya gerak menyembah atau menabur bunga, disebut gerak ....", options: ["Murni", "Lurus", "Maknawi", "Bebas"], answer: 2, solution: "1. Gerak tari dibedakan menjadi dua jenis. 2. Gerak murni hanya mengutamakan keindahan tanpa arti, sedangkan gerak yang mengandung arti atau maksud disebut gerak maknawi. 3. Contoh gerak maknawi adalah gerak menyembah yang berarti menghormati." },
    { q: "Tari Piring berasal dari ....", options: ["Sumatera Utara", "Sumatera Selatan", "Jawa Barat", "Sumatera Barat"], answer: 3, solution: "1. Tari Piring ditarikan sambil membawa piring di kedua telapak tangan. 2. Tari ini berasal dari masyarakat Minangkabau. 3. Masyarakat Minangkabau berada di Sumatera Barat." },
    { q: "Pola lantai tari yang berbentuk lingkaran biasanya melambangkan ....", options: ["Kebersamaan dan kesatuan", "Perpecahan", "Perjalanan yang jauh", "Kekuasaan seorang raja"], answer: 0, solution: "1. Pola lantai adalah garis khayal yang dilalui penari di atas panggung. 2. Lingkaran adalah garis yang menyambung tanpa ujung dan tanpa putus. 3. Bentuk yang menyambung ini melambangkan kebersamaan dan kesatuan." },
    { q: "Tari Jaipong berasal dari ....", options: ["Jawa Tengah", "Jawa Barat", "Banten", "DKI Jakarta"], answer: 1, solution: "1. Tari Jaipong memiliki gerakan yang energik dengan iringan kendang yang khas. 2. Jaipong berkembang dari kesenian rakyat Sunda. 3. Daerah Sunda adalah Jawa Barat, jadi Tari Jaipong berasal dari Jawa Barat." },
    { q: "Tiga unsur utama dalam menari yang disingkat 3W adalah ....", options: ["Wibawa, wirasa, wiraga", "Wiraga, wirasa, wisata", "Wiraga, wirama, wirasa", "Wirama, wirasa, wacana"], answer: 2, solution: "1. Kualitas tarian dinilai dari tiga unsur pokok yang disingkat 3W. 2. Wiraga adalah gerak tubuh penari, wirama adalah kesesuaian gerak dengan irama, dan wirasa adalah penghayatan rasa. 3. Jadi 3W = wiraga, wirama, wirasa." },
    { q: "Tari Tor-Tor berasal dari ....", options: ["Sumatera Barat", "Aceh", "Sumatera Selatan", "Sumatera Utara"], answer: 3, solution: "1. Tari Tor-Tor diiringi bunyi gondang (gendang khas Batak). 2. Tari ini berasal dari suku Batak. 3. Suku Batak berada di Sumatera Utara, jadi Tari Tor-Tor berasal dari Sumatera Utara." },
    { q: "Fungsi properti dalam sebuah tarian adalah ....", options: ["Membantu memperjelas karakter dan memperindah tarian", "Menggantikan gerakan penari", "Menjadi pengganti musik pengiring", "Mengatur jumlah penonton"], answer: 0, solution: "1. Properti adalah benda yang dipakai penari, misalnya kipas, piring, atau selendang. 2. Properti membantu memperjelas tokoh yang diperankan dan memperindah tarian. 3. Properti tidak menggantikan gerak penari maupun musik pengiring." },
    { q: "Tari Pendet pada awalnya berfungsi sebagai ....", options: ["Tari perang", "Tari penyambutan dan pemujaan", "Tari pernikahan", "Tari panen raya"], answer: 1, solution: "1. Tari Pendet ditarikan oleh penari perempuan yang membawa bokor berisi bunga. 2. Pada awalnya tari ini dipentaskan untuk upacara pemujaan di pura. 3. Kini Tari Pendet juga dikenal sebagai tari penyambutan tamu di Bali." },
    { q: "Orang yang bertugas mengatur dan mengarahkan jalannya pementasan teater disebut ....", options: ["Aktor", "Penonton", "Sutradara", "Penata rias"], answer: 2, solution: "1. Pementasan teater membutuhkan satu orang yang menjadi pengarah keseluruhan. 2. Ia mengatur akting pemain, gerak di panggung, tata lampu, dan jalannya cerita. 3. Orang tersebut disebut sutradara." },
    { q: "Naskah dalam pementasan teater berfungsi sebagai ....", options: ["Hiasan panggung", "Daftar hadir penonton", "Jadwal latihan", "Pedoman cerita dan dialog para pemain"], answer: 3, solution: "1. Para pemain perlu tahu alur cerita dan kalimat yang harus diucapkan. 2. Semua itu tertulis dalam naskah lakon. 3. Jadi naskah berfungsi sebagai pedoman cerita dan dialog para pemain." },
    { q: "Panggung yang penontonnya duduk mengelilingi area pertunjukan dari semua sisi disebut panggung ....", options: ["Arena", "Proscenium", "Thrust", "Pendopo"], answer: 0, solution: "1. Jenis panggung dibedakan menurut posisi penonton terhadap area pertunjukan. 2. Pada panggung proscenium penonton hanya duduk di satu sisi depan. 3. Panggung yang penontonnya mengelilingi dari semua sisi disebut panggung arena." },
    { q: "Ketoprak, ludruk, dan lenong termasuk jenis teater ....", options: ["Modern", "Tradisional", "Kontemporer", "Musikal"], answer: 1, solution: "1. Ketoprak berasal dari Jawa, ludruk dari Jawa Timur, dan lenong dari Betawi. 2. Ketiganya lahir dari tradisi rakyat dengan ciri cerita rakyat, bahasa daerah, dan iringan musik tradisional. 3. Jadi ketiganya termasuk teater tradisional." },
    { q: "Tata rias dalam pementasan teater bertujuan untuk ....", options: ["Membuat pemain terlihat cantik saja", "Menutupi wajah pemain", "Mengubah wajah pemain sesuai karakter tokoh", "Menggantikan fungsi kostum"], answer: 2, solution: "1. Tokoh dalam teater bermacam-macam: ada yang tua, muda, jahat, atau baik. 2. Wajah pemain diubah dengan riasan agar sesuai dengan karakter tokoh yang diperankan. 3. Tujuannya memperkuat karakter tokoh, bukan sekadar mempercantik wajah." },
    { q: "Istilah 'blocking' dalam dunia teater berarti ....", options: ["Menutup panggung dengan tirai", "Mematikan lampu panggung", "Menghafal seluruh naskah", "Pengaturan gerak dan posisi pemain di panggung"], answer: 3, solution: "1. Setiap pemain harus tahu kapan masuk panggung, berdiri di mana, dan bergerak ke mana. 2. Pengaturan gerak dan posisi pemain di atas panggung ini disebut blocking. 3. Blocking ditentukan oleh sutradara pada saat latihan." },
    { q: "Benda-benda pendukung di atas panggung seperti meja, kursi, dan pedang mainan dalam teater disebut ....", options: ["Properti", "Dekorasi dinding", "Kostum", "Naskah"], answer: 0, solution: "1. Selain pemain, pementasan teater membutuhkan benda-benda pendukung. 2. Benda seperti meja, kursi, dan pedang mainan disebut properti panggung. 3. Kostum adalah pakaian yang dikenakan pemain, sedangkan naskah adalah pedoman cerita." },
    { q: "Dialog yang diucapkan pemain seolah-olah berbicara sendiri untuk mengungkapkan isi hatinya kepada penonton disebut ....", options: ["Prolog", "Monolog", "Epilog", "Dialog"], answer: 1, solution: "1. Kadang seorang pemain berbicara sendirian di atas panggung. 2. Ucapan seorang diri yang mengungkapkan isi hati tokoh disebut monolog. 3. Prolog ada di awal cerita, epilog di akhir cerita, sedangkan dialog melibatkan dua orang atau lebih." },
{ q: "Unsur seni rupa berupa goresan atau coretan yang berfungsi sebagai pembatas dan pembentuk bidang adalah ....", options: ["Garis","Warna","Ruang","Tekstur"], answer: 0, solution: "1. Garis adalah unsur berupa goresan memanjang yang dibuat dengan alat gambar. 2. Garis berfungsi sebagai pembatas antara satu area dengan area lain. 3. Rangkaian garis yang saling terhubung akan membentuk bidang." },
{ q: "Gabungan beberapa garis yang saling terhubung sehingga membentuk area datar seperti lingkaran atau segitiga disebut ....", options: ["Bentuk","Bidang","Ruang","Volume"], answer: 1, solution: "1. Ketika garis-garis saling bertemu dan menutup, terbentuklah area datar. 2. Area datar ini disebut bidang, misalnya lingkaran, segitiga, dan persegi. 3. Bidang bersifat dua dimensi (panjang dan lebar), belum memiliki volume." },
{ q: "Unsur seni rupa yang memiliki panjang, lebar, dan tinggi sehingga tampak bervolume seperti kubus dan bola disebut ....", options: ["Titik","Bidang","Garis","Bentuk (bangun)"], answer: 3, solution: "1. Bidang-bidang yang disusun menjadi satu kesatuan akan menghasilkan unsur yang bervolume. 2. Unsur ini disebut bentuk atau bangun, misalnya kubus, bola, dan tabung. 3. Berbeda dengan bidang yang datar, bentuk memiliki tiga dimensi: panjang, lebar, dan tinggi." },
{ q: "Ruang pada karya lukisan disebut ruang semu karena ....", options: ["memiliki volume seperti patung","benar-benar bisa dimasuki","hanya kesan kedalaman pada bidang datar","dibuat dari bahan tiga dimensi"], answer: 2, solution: "1. Ruang adalah unsur berupa rongga atau kesan kedalaman dalam karya seni. 2. Pada lukisan yang datar, kedalaman hanya kesan yang dibuat lewat perspektif dan gelap-terang. 3. Karena tidak benar-benar memiliki rongga, ruang pada lukisan disebut ruang semu." },
{ q: "Unsur gelap-terang pada gambar berfungsi untuk ....", options: ["menambah jumlah garis pada gambar","memperbesar ukuran kertas gambar","menimbulkan kesan volume dan kedalaman","membuat gambar menjadi berwarna-warni"], answer: 2, solution: "1. Gelap-terang adalah perbedaan intensitas cahaya pada suatu gambar. 2. Bagian yang gelap memberi kesan menjauh atau cekung, bagian terang memberi kesan menonjol. 3. Dengan begitu gambar dua dimensi tampak bervolume dan memiliki kedalaman." },
{ q: "Sebagai unsur seni rupa, warna berfungsi untuk ....", options: ["membedakan objek dan menyampaikan suasana","membuat garis menjadi lebih tebal","menghilangkan kesan ruang","menambah berat karya seni"], answer: 0, solution: "1. Warna adalah unsur yang paling mudah menarik perhatian mata. 2. Warna membantu membedakan satu objek dengan objek lain dalam gambar. 3. Warna juga menyampaikan suasana hati, misalnya merah terasa berani dan biru terasa tenang." },
{ q: "Gambar yang hanya dibuat dari garis-garis tepi tanpa pewarnaan di dalamnya disebut gambar ....", options: ["Aquarel","Arsir","Siluet","Kontur (outline)"], answer: 3, solution: "1. Garis tepi yang mengikuti bentuk luar objek disebut garis kontur atau outline. 2. Gambar yang hanya terdiri dari garis kontur tanpa isian warna disebut gambar kontur. 3. Gambar kontur biasanya menjadi dasar sebelum diberi warna atau gelap-terang." },
{ q: "Garis vertikal memberi kesan ....", options: ["bergerak dan dinamis","lembut dan luwes","tenang dan luas","tegak, kokoh, dan agung"], answer: 3, solution: "1. Garis vertikal adalah garis yang berdiri tegak dari atas ke bawah. 2. Arah tegak menyerupai tiang dan pohon yang berdiri kokoh. 3. Karena itu garis vertikal memberi kesan tegak, kokoh, stabil, dan agung." },
{ q: "Garis horizontal seperti garis cakrawala memberi kesan ....", options: ["tenang, damai, dan luas","tegang dan gelisah","bergerak cepat","megah dan kokoh"], answer: 0, solution: "1. Garis horizontal adalah garis mendatar dari kiri ke kanan. 2. Arah mendatar menyerupai permukaan laut dan cakrawala yang tenang. 3. Karena itu garis horizontal memberi kesan tenang, damai, dan luas." },
{ q: "Garis diagonal memberi kesan ....", options: ["tenang dan stabil","lembut dan indah","gerak, dinamis, dan tidak stabil","kaku dan formal"], answer: 2, solution: "1. Garis diagonal adalah garis miring yang tidak tegak maupun mendatar. 2. Posisi miring seolah-olah akan jatuh atau sedang bergerak. 3. Karena itu garis diagonal memberi kesan gerak, dinamis, dan kurang stabil." },
{ q: "Garis lengkung memberi kesan ....", options: ["tajam dan tegang","lembut, luwes, dan indah","kaku dan tegas","kokoh dan agung"], answer: 1, solution: "1. Garis lengkung adalah garis yang melengkung tanpa sudut tajam. 2. Lengkungan menyerupai ombak, awan, dan lekuk tubuh yang halus. 3. Karena itu garis lengkung memberi kesan lembut, luwes, dan indah." },
{ q: "Garis zigzag memberi kesan ....", options: ["lembut dan mengalir","megah dan stabil","tenang dan damai","tajam, penuh semangat, dan gelisah"], answer: 3, solution: "1. Garis zigzag adalah garis patah-patah dengan sudut-sudut tajam. 2. Sudut tajam yang berulang memberi kesan seperti petir yang menyambar. 3. Karena itu garis zigzag memberi kesan tajam, penuh semangat, dan gelisah." },
{ q: "Garis lurus memberi kesan ....", options: ["dinamis dan bergerak","gelisah dan tajam","tegas, kaku, dan formal","lembut dan mengalir"], answer: 2, solution: "1. Garis lurus adalah garis yang ditarik lurus tanpa lengkungan. 2. Sifatnya yang tidak melengkung memberi kesan disiplin dan teratur. 3. Karena itu garis lurus memberi kesan tegas, kaku, dan formal." },
{ q: "Prinsip seni rupa yang menuntut semua unsur saling mendukung sehingga karya terasa menyatu dan utuh disebut ....", options: ["Kesatuan (unity)","Kontras","Proporsi","Gradasi"], answer: 0, solution: "1. Karya seni tersusun dari banyak unsur seperti garis, warna, dan bidang. 2. Jika unsur-unsur itu saling mendukung dan tidak bertentangan, karya terasa menyatu. 3. Prinsip ini disebut kesatuan atau unity: semua bagian menjadi satu kesatuan yang utuh." },
{ q: "Bagian karya seni yang dibuat paling menonjol untuk menjadi pusat perhatian disebut ....", options: ["Latar","Penekanan (emphasis)","Bingkai","Sketsa"], answer: 1, solution: "1. Dalam sebuah karya, biasanya ada satu bagian yang ingin ditonjolkan seniman. 2. Bagian itu dibuat berbeda, misalnya lebih besar, lebih terang, atau warnanya mencolok. 3. Prinsip menonjolkan pusat perhatian ini disebut penekanan atau emphasis." },
{ q: "Prinsip seni rupa yang mengatur perbandingan ukuran antar bagian objek agar tampak serasi disebut ....", options: ["Proporsi","Harmoni","Kesatuan","Irama"], answer: 0, solution: "1. Setiap objek tersusun dari bagian-bagian dengan ukuran tertentu. 2. Jika perbandingan ukurannya tepat, objek tampak wajar dan serasi. 3. Prinsip yang mengatur perbandingan ukuran ini disebut proporsi." },
{ q: "Paduan unsur-unsur seni rupa yang serasi dan tidak bertentangan sehingga enak dipandang menunjukkan prinsip ....", options: ["Kontras","Gradasi","Repetisi","Harmoni (keselarasan)"], answer: 3, solution: "1. Warna, bentuk, dan garis dalam karya harus saling cocok satu sama lain. 2. Ketika semuanya selaras dan tidak saling bertentangan, karya terasa nyaman dipandang. 3. Prinsip keselarasan paduan unsur ini disebut harmoni." },
{ q: "Perubahan warna atau ukuran secara bertahap dari terang ke gelap atau dari besar ke kecil dalam karya seni disebut ....", options: ["Penekanan","Kesatuan","Kontras","Gradasi"], answer: 3, solution: "1. Kadang seniman mengubah warna atau ukuran sedikit demi sedikit. 2. Perubahan halus dan bertahap ini misalnya dari merah muda ke merah tua. 3. Prinsip perubahan bertahap tersebut disebut gradasi." },
{ q: "Warna oranye, hijau, dan ungu termasuk warna sekunder karena ....", options: ["merupakan warna dasar cat","tidak bisa dicampur dari warna lain","dihasilkan dari campuran dua warna primer","hanya ada di lingkaran warna"], answer: 2, solution: "1. Warna primer adalah merah, kuning, dan biru yang tidak bisa dibuat dari campuran. 2. Jika dua warna primer dicampur, misalnya merah dan kuning, hasilnya oranye. 3. Warna hasil campuran dua warna primer inilah yang disebut warna sekunder: oranye, hijau, dan ungu." },
{ q: "Warna tersier adalah warna yang dihasilkan dari campuran ....", options: ["warna hitam dan putih","dua warna primer","warna primer dan warna sekunder","tiga warna primer sekaligus"], answer: 2, solution: "1. Warna primer dicampur dengan warna sekunder menghasilkan warna baru. 2. Misalnya merah (primer) dicampur oranye (sekunder) menjadi merah-oranye. 3. Warna hasil campuran primer dan sekunder ini disebut warna tersier, seperti kuning-hijau dan biru-ungu." },
{ q: "Pasangan warna merah dan hijau disebut warna komplementer karena ....", options: ["keduanya warna dingin","letaknya berdekatan di lingkaran warna","letaknya berseberangan di lingkaran warna","keduanya warna primer"], answer: 2, solution: "1. Warna komplementer adalah pasangan warna yang saling melengkapi. 2. Letaknya berseberangan dalam lingkaran warna, seperti merah dengan hijau. 3. Pasangan komplementer memberi kesan kontras yang kuat: kuning-ungu dan biru-oranye." },
{ q: "Warna merah, oranye, dan kuning termasuk warna panas karena memberi kesan ....", options: ["berani, semangat, dan hangat","sedih dan muram","dingin dan jauh","tenang dan sejuk"], answer: 0, solution: "1. Warna panas mengingatkan pada api dan sinar matahari. 2. Merah, oranye, dan kuning termasuk kelompok warna panas. 3. Warna-warna ini memberi kesan berani, bersemangat, hangat, dan menarik perhatian." },
{ q: "Warna biru, hijau, dan ungu termasuk warna dingin karena memberi kesan ....", options: ["panas dan menyala","tegang dan gelisah","tenang, sejuk, dan damai","berani dan bersemangat"], answer: 2, solution: "1. Warna dingin mengingatkan pada air, langit, dan dedaunan. 2. Biru, hijau, dan ungu termasuk kelompok warna dingin. 3. Warna-warna ini memberi kesan tenang, sejuk, damai, dan menenangkan." },
{ q: "Teknik menggambar dengan membuat goresan-goresan garis sejajar atau menyilang untuk menimbulkan kesan gelap-terang disebut ....", options: ["Siluet","Aquarel","Arsir","Blok"], answer: 2, solution: "1. Kesan gelap bisa dibuat dengan menumpuk goresan garis. 2. Semakin rapat dan banyak goresannya, semakin gelap hasilnya. 3. Teknik menggambar dengan goresan garis sejajar atau menyilang ini disebut arsir." },
{ q: "Teknik mewarnai gambar dengan satu warna datar yang merata menutup seluruh bidang disebut teknik ....", options: ["Pointilis","Blok","Dusel","Arsir"], answer: 1, solution: "1. Kadang gambar diwarnai dengan warna yang rata tanpa gradasi. 2. Seluruh bidang ditutup satu warna yang sama dan merata. 3. Teknik pewarnaan datar dan merata ini disebut teknik blok." },
{ q: "Gambar yang hanya menampilkan bayangan hitam pekat dari bentuk objek tanpa detail di dalamnya disebut ....", options: ["Aquarel","Mozaik","Sketsa","Siluet"], answer: 3, solution: "1. Jika objek difoto membelakangi cahaya, yang terlihat hanya bayangan gelapnya. 2. Gambar yang meniru bayangan gelap ini hanya berwarna hitam tanpa detail dalam. 3. Gambar bayangan hitam tanpa detail tersebut disebut siluet." },
{ q: "Gambar kasar dan cepat yang dibuat sebagai rancangan awal sebelum menggambar yang sebenarnya disebut ....", options: ["Sketsa","Poster","Karikatur","Lukisan"], answer: 0, solution: "1. Seniman biasanya tidak langsung menggambar karya final. 2. Ia membuat rancangan cepat untuk menentukan bentuk dan komposisi. 3. Gambar rancangan yang kasar dan cepat ini disebut sketsa." },
{ q: "Teknik melukis menggunakan cat air dengan sapuan tipis dan transparan disebut teknik ....", options: ["Aquarel","Arsir","Blok","Plakat"], answer: 0, solution: "1. Cat air dilarutkan dengan air sehingga warnanya tipis. 2. Sapuannya transparan dan warna di bawahnya masih bisa terlihat. 3. Teknik melukis cat air dengan sapuan tipis transparan ini disebut aquarel." },
{ q: "Benda-benda seperti kotak pensil, dadu, dan kardus digolongkan sebagai bentuk kubistis karena ....", options: ["menyerupai tabung","menyerupai kubus atau balok","menyerupai bola","menyerupai kerucut"], answer: 1, solution: "1. Bentuk kubistis adalah bentuk yang menyerupai kubus. 2. Kotak pensil, dadu, dan kardus memiliki sisi-sisi datar seperti kubus atau balok. 3. Karena itu benda-benda tersebut digolongkan sebagai bentuk kubistis." },
{ q: "Benda-benda seperti gelas, botol, dan kaleng digolongkan sebagai bentuk silindris karena ....", options: ["menyerupai bola","menyerupai tabung","menyerupai prisma","menyerupai kubus"], answer: 1, solution: "1. Bentuk silindris adalah bentuk yang menyerupai silinder atau tabung. 2. Gelas, botol, dan kaleng memiliki badan berbentuk tabung. 3. Karena itu benda-benda tersebut digolongkan sebagai bentuk silindris." },
{ q: "Langkah yang tepat saat mulai menggambar bunga adalah ....", options: ["membuat bentuk dasar sederhana seperti lingkaran","mewarnai gambar terlebih dahulu","menggambar latar belakang dulu","langsung menggambar detail kelopaknya"], answer: 0, solution: "1. Menggambar langsung detail sering membuat bentuk bunga tidak proporsional. 2. Bunga bisa disederhanakan menjadi bentuk dasar seperti lingkaran untuk mahkota. 3. Setelah bentuk dasar benar, barulah ditambah detail kelopak dan tangkai." },
{ q: "Ragam hias adalah ....", options: ["gambar pemandangan alam","hiasan atau ornamen yang disusun berulang sebagai dekorasi","teknik mewarnai batik","alat untuk mengukir kayu"], answer: 1, solution: "1. Banyak benda seni dihiasi pola-pola indah agar menarik. 2. Pola hiasan yang dibuat berulang-ulang untuk dekorasi disebut ragam hias. 3. Ragam hias bisa ditemukan pada batik, ukiran, tenun, dan bangunan." },
{ q: "Ragam hias yang tersusun dari garis, lingkaran, segitiga, dan bentuk geometri lainnya disebut ragam hias ....", options: ["Figuratif","Flora","Fauna","Geometris"], answer: 3, solution: "1. Ragam hias dibedakan berdasarkan sumber bentuknya. 2. Jika bentuknya berasal dari bangun geometri seperti garis dan lingkaran, disebut ragam hias geometris. 3. Contohnya motif kawung dan motif tumpal pada kain." },
{ q: "Ragam hias yang bentuknya terinspirasi dari tumbuhan seperti daun, bunga, dan sulur disebut ragam hias ....", options: ["Flora","Figuratif","Geometris","Fauna"], answer: 0, solution: "1. Ragam hias flora mengambil bentuk dari dunia tumbuhan. 2. Daun, bunga, dan sulur digayakan menjadi pola hiasan yang indah. 3. Contohnya motif bunga pada batik dan ukiran Jepara." },
{ q: "Ragam hias yang bentuknya terinspirasi dari hewan seperti burung, ikan, dan kupu-kupu disebut ragam hias ....", options: ["Figuratif","Flora","Geometris","Fauna"], answer: 3, solution: "1. Ragam hias fauna mengambil bentuk dari dunia hewan. 2. Burung, ikan, dan kupu-kupu digayakan menjadi pola dekoratif. 3. Contohnya motif burung hong pada batik dan ukiran." },
{ q: "Ragam hias yang bentuknya menyerupai manusia, baik seluruh tubuh maupun bagian tertentu, disebut ragam hias ....", options: ["Figuratif","Flora","Fauna","Geometris"], answer: 0, solution: "1. Ragam hias figuratif mengambil bentuk dari sosok manusia. 2. Bisa berupa seluruh tubuh atau bagian tubuh seperti wajah yang digayakan. 3. Contohnya relief manusia pada candi dan patung hias." },
{ q: "Batik tulis dibuat dengan cara ....", options: ["mencetak motif dengan stempel tembaga","menorehkan malam panas dengan canting","menyablon dengan screen","mencelup kain tanpa pola"], answer: 1, solution: "1. Batik tulis adalah batik yang dibuat sepenuhnya dengan tangan. 2. Pembatik menorehkan malam (lilin) panas ke kain menggunakan canting. 3. Karena dikerjakan manual satu per satu, batik tulis memiliki nilai seni tinggi." },
{ q: "Batik cap dibuat dengan cara ....", options: ["menenun benang berwarna","menorehkan malam dengan canting","menekan stempel tembaga bermotif ke kain","melukis motif dengan kuas"], answer: 2, solution: "1. Batik cap dibuat untuk mempercepat proses produksi batik. 2. Motif batik diukir pada stempel tembaga yang dicelup malam panas. 3. Stempel itu kemudian ditekan ke kain sehingga motif tercetak cepat dan seragam." },
{ q: "Canting adalah alat batik yang berfungsi untuk ....", options: ["menorehkan malam cair ke kain","memotong kain batik","mengeringkan kain batik","mencelup kain ke pewarna"], answer: 0, solution: "1. Canting terbuat dari tembaga dengan gagang bambu dan ujung bercucuk. 2. Malam (lilin) panas dimasukkan ke wadah canting lalu menetes dari cucuknya. 3. Dengan canting, pembatik menorehkan garis-garis motif malam ke atas kain." },
{ q: "Motif batik kawung memiliki ciri khas ....", options: ["empat kelopak bunga yang tersusun geometris","garis-garis diagonal miring","gambar hewan naga","gambar awan berarak"], answer: 0, solution: "1. Motif kawung adalah salah satu motif batik tertua dari Jawa. 2. Bentuknya berupa empat kelopak bunga (seperti buah aren) yang tersusun simetris geometris. 3. Motif ini melambangkan kesucian dan keadilan." },
{ q: "Motif batik mega mendung memiliki ciri khas ....", options: ["kelopak bunga empat simetris","garis diagonal seperti pedang","lingkaran-lingkaran kecil","awan berarak dengan gradasi warna"], answer: 3, solution: "1. Mega mendung adalah motif batik khas Cirebon. 2. Motifnya berupa gambar awan yang berarak dengan gradasi warna, biasanya biru. 3. Awan melambangkan ketenangan dan kesabaran." },
{ q: "Motif batik parang memiliki ciri khas ....", options: ["bentuk awan berarak","garis-garis diagonal miring berulang","kelopak bunga simetris","gambar binatang"], answer: 1, solution: "1. Motif parang adalah motif batik klasik dari keraton Jawa. 2. Bentuknya berupa garis-garis diagonal miring yang tersusun berulang seperti lereng atau bilah pedang. 3. Motif ini melambangkan semangat pantang menyerah." },
{ q: "Teknik membuat patung dengan menuangkan bahan cair seperti perunggu atau gips ke dalam cetakan disebut teknik ....", options: ["Butsir","Ukir","Pahat","Cor (cetak)"], answer: 3, solution: "1. Bahan seperti perunggu dilelehkan hingga menjadi cair. 2. Cairan itu dituang ke dalam cetakan yang sudah berbentuk patung. 3. Setelah dingin dan mengeras, cetakan dibuka dan jadilah patung, teknik ini disebut cor atau cetak." },
{ q: "Teknik membuat patung dengan cara merakit atau menyusun bahan-bahan seperti besi, kayu, dan kawat disebut teknik ....", options: ["Pahat","Butsir","Konstruksi","Cor"], answer: 2, solution: "1. Tidak semua patung dibentuk dari satu bahan utuh. 2. Ada patung yang dibuat dengan merakit potongan besi, kayu, atau kawat memakai las dan paku. 3. Teknik menyusun dan merakit bahan menjadi patung ini disebut teknik konstruksi." },
{ q: "Berikut ini yang termasuk bahan lunak untuk membuat patung adalah ....", options: ["Kayu jati","Tanah liat","Perunggu","Batu granit"], answer: 1, solution: "1. Bahan patung dibedakan menjadi lunak, sedang, dan keras. 2. Bahan lunak mudah dibentuk dengan tangan, misalnya tanah liat, plastisin, sabun, dan lilin. 3. Batu granit dan perunggu termasuk bahan keras, sedangkan kayu termasuk bahan sedang." },
{ q: "Kayu termasuk bahan sedang untuk membuat patung karena ....", options: ["sangat mudah dibentuk dengan jari","lebih keras dari tanah liat tetapi lebih lunak dari batu","harus dilelehkan dulu","hanya bisa dirakit dengan las"], answer: 1, solution: "1. Kayu tidak bisa dipijat dengan jari seperti tanah liat. 2. Namun kayu juga tidak sekeras batu yang harus dipahat dengan pahat besi. 3. Karena tingkat kekerasannya di antara tanah liat dan batu, kayu digolongkan sebagai bahan sedang." },
{ q: "Berikut ini yang termasuk bahan keras untuk membuat patung adalah ....", options: ["Plastisin","Sabun","Batu marmer","Lilin"], answer: 2, solution: "1. Bahan keras sulit dibentuk dan membutuhkan alat pahat khusus. 2. Batu marmer, granit, dan andesit termasuk bahan keras. 3. Plastisin, sabun, dan lilin justru termasuk bahan lunak yang mudah dibentuk." },
{ q: "Patung yang hanya menampilkan bagian dada hingga kepala disebut patung ....", options: ["Zonde","Torso","Bust (busto)","Relief"], answer: 2, solution: "1. Patung dibedakan berdasarkan bagian tubuh yang ditampilkan. 2. Patung yang menampilkan dada hingga kepala disebut bust atau busto. 3. Berbeda dengan torso yang hanya badan tanpa kepala, dan zonde yang menampilkan seluruh tubuh utuh." },
{ q: "Patung yang menampilkan seluruh tubuh manusia secara utuh dari kepala sampai kaki disebut patung ....", options: ["Torso","Bust","Relief","Zonde"], answer: 3, solution: "1. Patung zonde menampilkan sosok manusia secara lengkap. 2. Dari kepala, badan, hingga kaki semuanya dibuat utuh. 3. Berbeda dengan bust yang hanya dada ke atas dan torso yang hanya badan tanpa kepala." },
{ q: "Pada seni grafis cetak tinggi, bagian yang dicetak dengan tinta adalah ....", options: ["bagian yang dilubangi","bagian yang dalam atau tercukil","bagian yang tinggi atau menonjol","bagian kain screen"], answer: 2, solution: "1. Cetak tinggi adalah teknik cetak tertua, misalnya cukilan kayu. 2. Permukaan yang menonjol (tinggi) diolesi tinta lalu ditekan ke kertas. 3. Jadi bagian yang mencetak gambar adalah bagian yang tinggi atau menonjol." },
{ q: "Pada seni grafis cetak dalam, tinta diletakkan pada ....", options: ["stempel tembaga","permukaan yang menonjol","kain screen yang berpori","bagian yang dalam atau tercukil"], answer: 3, solution: "1. Cetak dalam kebalikan dari cetak tinggi, misalnya teknik etsa. 2. Gambar digoreskan ke dalam pelat logam sehingga membentuk ceruk. 3. Tinta dimasukkan ke dalam ceruk itu, lalu pelat ditekan ke kertas." },
{ q: "Teknik sablon termasuk jenis cetak saring karena ....", options: ["menggunakan stempel tembaga","memahat kayu yang menonjol","menggores pelat logam","tinta didorong melewati kain screen berpori"], answer: 3, solution: "1. Sablon memakai bingkai kain halus berpori yang disebut screen. 2. Bagian yang tidak bergambar ditutup, bagian bergambar dibiarkan berpori. 3. Tinta didorong dengan rakel melewati pori-pori screen ke atas kaos atau kertas." },
{ q: "Lukisan termasuk karya seni dua dimensi karena ....", options: ["memiliki volume dan bisa diraba","hanya memiliki panjang dan lebar pada bidang datar","dibuat dengan teknik memahat","berdiri tegak seperti patung"], answer: 1, solution: "1. Karya dua dimensi hanya bisa dinikmati dari satu sisi. 2. Lukisan dibuat di atas kanvas atau kertas yang datar. 3. Ia hanya memiliki panjang dan lebar, tanpa ketebalan atau volume yang nyata." },
{ q: "Poster termasuk karya seni rupa dua dimensi yang berfungsi untuk ....", options: ["dimasukkan ke dalam cetakan","dipahat dari batu","menyampaikan pesan atau informasi secara singkat dan menarik","duduk dan dipakai sehari-hari"], answer: 2, solution: "1. Poster adalah karya grafis yang dipajang di tempat umum. 2. Isinya berupa gambar dan tulisan singkat yang mudah dibaca. 3. Fungsinya menyampaikan pesan, ajakan, atau informasi secara cepat dan menarik." },
{ q: "Karikatur memiliki ciri khas ....", options: ["menyalin foto secara persis","hanya memakai warna hitam putih","melebih-lebihkan ciri khas objek dengan gaya lucu","menggambar objek seindah-indahnya"], answer: 2, solution: "1. Karikatur adalah gambar yang bersifat humor dan sindiran. 2. Ciri khas seseorang, misalnya hidung besar, digambar berlebih-lebihan. 3. Tujuannya menghibur sekaligus menyampaikan kritik dengan cara lucu." },
{ q: "Mozaik adalah karya seni yang dibuat dengan cara ....", options: ["menempelkan potongan-potongan kecil menjadi gambar","menuang logam cair ke cetakan","menggores pelat logam","memahat batu menjadi bentuk"], answer: 0, solution: "1. Mozaik dibuat dari kepingan-kepingan kecil bahan. 2. Potongan kaca, keramik, atau batu ditempel satu per satu. 3. Susunan potongan kecil itu membentuk gambar atau pola yang utuh." },
{ q: "Kolase adalah karya seni yang dibuat dengan cara ....", options: ["menempelkan berbagai bahan berbeda di atas bidang","mencetak dengan screen","memahat dari kayu","melukis dengan cat minyak"], answer: 0, solution: "1. Kolase berasal dari kata coller yang artinya menempel. 2. Bahan yang ditempel bermacam-macam: kertas, kain, daun kering, dan plastik. 3. Aneka bahan berbeda itu disusun di atas bidang menjadi karya baru." },
{ q: "Montase adalah karya seni yang dibuat dengan cara ....", options: ["menggabungkan potongan-potongan foto menjadi gambar baru","menempelkan kepingan keramik kecil","menuang gips ke cetakan","mengukir kayu Jepara"], answer: 0, solution: "1. Montase memakai potongan-potongan foto sebagai bahan utama. 2. Potongan foto dari berbagai sumber digunting lalu disusun ulang. 3. Gabungan potongan foto itu membentuk gambar baru yang utuh dan bermakna." },
{ q: "Relief pada dinding candi termasuk karya tiga dimensi karena ....", options: ["memiliki volume dan tonjolan yang bisa diraba","dibuat di atas kertas datar","tidak memiliki ketebalan","hanya bisa dilihat dari depan"], answer: 0, solution: "1. Relief adalah pahatan yang menempel pada dinding. 2. Gambarnya timbul keluar dari permukaan sehingga memiliki ketebalan. 3. Karena memiliki volume dan bisa diraba tonjolannya, relief termasuk karya tiga dimensi." },
{ q: "Kanvas adalah media melukis berupa ....", options: ["kain tebal berbingkai untuk melukis","papan kayu untuk memahat","kain screen untuk sablon","kertas tipis untuk sketsa"], answer: 0, solution: "1. Pelukis membutuhkan alas yang kuat untuk cat. 2. Kanvas adalah kain tebal yang dibentangkan pada bingkai kayu. 3. Di atas kanvas inilah lukisan cat minyak atau akrilik dibuat." },
{ q: "Cat akrilik memiliki keunggulan ....", options: ["tidak bisa dicampur dengan warna lain","cepat kering dan bisa dilarutkan dengan air","sangat lambat kering hingga berbulan-bulan","hanya bisa dipakai di atas kertas"], answer: 1, solution: "1. Cat akrilik berbahan dasar air sehingga praktis dipakai. 2. Kuas cukup dicuci dengan air, tidak perlu minyak khusus. 3. Cat ini cepat kering sehingga pelukis bisa menumpuk warna dalam waktu singkat." },
{ q: "Cat minyak memiliki sifat ....", options: ["cepat kering dalam hitungan menit","lambat kering sehingga warna bisa dicampur lama di kanvas","hanya menempel pada kertas","tidak bisa menghasilkan warna mengilap"], answer: 1, solution: "1. Cat minyak dicampur dengan minyak (linseed) bukan air. 2. Sifatnya lambat kering, bisa berhari-hari. 3. Kelebihannya, pelukis punya waktu lama untuk mencampur dan menghaluskan warna di atas kanvas." },
{ q: "Pensil 2B lebih cocok untuk menggambar sketsa gelap-terang dibanding pensil HB karena ....", options: ["batang grafitnya lebih lunak dan hitam","harganya lebih murah","lebih mudah dihapus","warnanya lebih terang"], answer: 0, solution: "1. Kode pada pensil menunjukkan tingkat kekerasan grafitnya. 2. Huruf B artinya black (hitam), semakin besar angkanya semakin lunak dan hitam. 3. Pensil 2B menghasilkan goresan lebih hitam dan lunak dibanding HB, cocok untuk arsir gelap." },
{ q: "Arang (charcoal) sebagai media gambar memiliki keunggulan ....", options: ["tidak bisa dihapus sama sekali","hanya untuk mewarnai batik","menghasilkan warna hitam pekat untuk gelap-terang","cepat kering seperti cat akrilik"], answer: 2, solution: "1. Arang gambar adalah batang karbon hitam untuk menggambar. 2. Goresannya menghasilkan warna hitam yang pekat dan mudah dibaurkan. 3. Karena itu arang sangat cocok untuk membuat kesan gelap-terang yang dramatis." },
{ q: "Pastel adalah media gambar berupa ....", options: ["bubuk arang hitam","tinta cetak sablon","cat cair dalam tube","batang berwarna lembut seperti kapur yang mudah dibaurkan"], answer: 3, solution: "1. Pastel berbentuk batang padat berisi pigmen warna. 2. Teksturnya lembut seperti kapur dan mudah dibaurkan dengan jari. 3. Warnanya cerah dan pekat sehingga cocok untuk gambar yang ekspresif." },
{ q: "Aliran seni lukis yang berusaha meniru alam seindah dan semirip mungkin disebut ....", options: ["Naturalisme","Kubisme","Ekspresionisme","Surealisme"], answer: 0, solution: "1. Kata naturalisme berasal dari nature yang artinya alam. 2. Pelukis aliran ini melukis pemandangan dan objek alam semirip mungkin. 3. Tujuannya menampilkan keindahan alam apa adanya, misalnya lukisan Basuki Abdullah." },
{ q: "Aliran seni lukis yang menggambarkan objek apa adanya tanpa dilebih-lebihkan atau diperindah disebut ....", options: ["Impresionisme","Surealisme","Romantisme","Realisme"], answer: 3, solution: "1. Realisme berasal dari kata real yang artinya nyata. 2. Pelukis realis menggambarkan kehidupan sehari-hari secara jujur. 3. Objek dilukis apa adanya, termasuk sisi yang kurang indah, tanpa dilebih-lebihkan." },
{ q: "Aliran seni lukis yang menonjolkan kisah dramatis, heroik, dan penuh emosi disebut ....", options: ["Impresionisme","Kubisme","Romantisme","Naturalisme"], answer: 2, solution: "1. Romantisme mengutamakan perasaan dan imajinasi yang meluap. 2. Lukisannya menampilkan peristiwa dramatis dan heroik yang menggugah emosi. 3. Contohnya lukisan Raden Saleh tentang penangkapan Pangeran Diponegoro yang penuh ketegangan." },
{ q: "Aliran seni lukis yang mengutamakan ungkapan perasaan pelukis secara spontan dengan goresan bebas dan warna berani disebut ....", options: ["Ekspresionisme","Realisme","Kubisme","Naturalisme"], answer: 0, solution: "1. Ekspresionisme berasal dari kata ekspresi, yaitu ungkapan perasaan. 2. Pelukisnya melukis secara spontan mengikuti gejolak batin, bukan meniru bentuk persis. 3. Goresannya bebas dan warnanya berani, seperti karya Affandi yang melukis langsung dengan tangan." },
{ q: "Aliran seni lukis yang menangkap kesan cahaya sesaat di alam terbuka disebut ....", options: ["Romantisme","Impresionisme","Ekspresionisme","Surealisme"], answer: 1, solution: "1. Impresionisme berasal dari kata impression yang artinya kesan. 2. Pelukisnya melukis di luar ruangan untuk menangkap perubahan cahaya matahari. 3. Hasilnya menampilkan kesan sesaat, misalnya gemerlap cahaya di permukaan air." },
{ q: "Aliran seni lukis yang menyederhanakan objek menjadi bentuk-bentuk geometris seperti kubus disebut ....", options: ["Surealisme","Kubisme","Romantisme","Naturalisme"], answer: 1, solution: "1. Kubisme berasal dari kata kubus (cube). 2. Pelukis aliran ini memecah objek menjadi bidang-bidang geometris. 3. Wajah atau gitar misalnya digambar sebagai susunan bentuk kotak dan segitiga, seperti karya Picasso." },
{ q: "Aliran seni lukis yang menggambarkan dunia mimpi dan khayalan yang tidak masuk akal disebut ....", options: ["Naturalisme","Realisme","Surealisme","Impresionisme"], answer: 2, solution: "1. Surealisme berasal dari kata sur yang artinya melampaui kenyataan. 2. Lukisannya menampilkan hal-hal aneh seperti jam yang meleleh. 3. Aliran ini menggambarkan dunia mimpi dan alam bawah sadar, contohnya karya Salvador Dali." },
{ q: "Raden Saleh dikenal sebagai pelukis Indonesia beraliran ....", options: ["Surealisme","Ekspresionisme","Romantisme","Kubisme"], answer: 2, solution: "1. Raden Saleh adalah pelukis Indonesia abad ke-19 yang belajar di Eropa. 2. Lukisannya menampilkan peristiwa dramatis penuh emosi kepahlawanan. 3. Karena ciri dramatis dan heroik itu, ia digolongkan beraliran romantisme, misalnya lukisan Penangkapan Pangeran Diponegoro." },
{ q: "Affandi dikenal sebagai pelukis Indonesia beraliran ....", options: ["Realisme","Ekspresionisme","Impresionisme","Naturalisme"], answer: 1, solution: "1. Affandi terkenal dengan cara melukis yang unik: langsung memencet cat dari tube. 2. Ia melukis dengan jari dan telapak tangan secara spontan mengikuti perasaan. 3. Goresan bebas dan warna berani yang penuh ekspresi itu menempatkannya dalam aliran ekspresionisme." },
{ q: "Basuki Abdullah dikenal sebagai pelukis Indonesia yang melukis ....", options: ["kesan cahaya sesaat","mimpi dan khayalan aneh","alam dan manusia seindah dan semirip mungkin","bentuk-bentuk kubus geometris"], answer: 2, solution: "1. Basuki Abdullah terkenal dengan lukisan potret dan pemandangan yang sangat mirip aslinya. 2. Ia melukis alam dan wajah manusia seindah dan semirip mungkin. 3. Karena itu ia digolongkan dalam aliran naturalisme (realis), misalnya lukisan Kakak dan Adik." },
{ q: "S. Sudjojono dijuluki Bapak Seni Rupa Modern Indonesia karena ....", options: ["memperkenalkan aliran kubisme","menjadi pelopor seni lukis modern yang jujur dan merakyat","melukis dengan teknik sablon","membuat patung dari perunggu"], answer: 1, solution: "1. S. Sudjojono hidup pada masa perjuangan kemerdekaan Indonesia. 2. Ia mempelopori seni lukis modern Indonesia yang jujur menggambarkan rakyat. 3. Pandangannya bahwa seni harus berpihak pada kebenaran membuatnya dijuluki Bapak Seni Rupa Modern Indonesia." },
{ q: "Tahap pertama dalam kritik seni rupa adalah deskripsi, yaitu ....", options: ["menilai bagus atau tidaknya karya","mencatat dan menjelaskan apa yang terlihat pada karya","menafsirkan makna karya","membandingkan dengan karya lain"], answer: 1, solution: "1. Kritik seni dilakukan bertahap: deskripsi, analisis, interpretasi, penilaian. 2. Tahap pertama adalah deskripsi, yaitu mengamati karya dengan saksama. 3. Pada tahap ini kita mencatat dan menjelaskan apa saja yang terlihat, misalnya objek, warna, dan ukurannya." },
{ q: "Tahap analisis dalam kritik seni rupa dilakukan dengan cara ....", options: ["menebak harga jual karya","menyalin karya tersebut","menilai karya bagus atau jelek","mengkaji unsur dan prinsip yang digunakan dalam karya"], answer: 3, solution: "1. Setelah mendeskripsikan karya, kritik berlanjut ke tahap analisis. 2. Pada tahap ini kita mengkaji bagaimana unsur (garis, warna) dan prinsip (keseimbangan, penekanan) dipakai. 3. Analisis membantu memahami cara seniman menyusun karyanya." },
{ q: "Tahap penilaian (evaluasi) dalam kritik seni rupa bertujuan untuk ....", options: ["menggambar ulang karya tersebut","menentukan kualitas karya disertai alasan","menghitung jumlah warna","menjual karya ke kolektor"], answer: 1, solution: "1. Penilaian adalah tahap akhir kritik setelah deskripsi, analisis, dan interpretasi. 2. Pada tahap ini kritikus memutuskan apakah karya berhasil atau tidak. 3. Keputusan itu harus disertai alasan yang jelas, misalnya kesatuan dan keaslian idenya." },
{ q: "Kurator dalam sebuah pameran seni bertugas ....", options: ["menyeleksi karya dan mengatur penyelenggaraannya","menjual tiket masuk pameran","membersihkan ruang pameran","melukis semua karya yang dipamerkan"], answer: 0, solution: "1. Pameran seni membutuhkan orang yang mengatur keseluruhan acara. 2. Kurator bertugas menyeleksi karya yang layak dipamerkan sesuai tema. 3. Ia juga mengatur tata letak karya dan menyusun konsep pameran agar menarik." },
{ q: "Gambar perspektif dengan dua titik hilang biasanya digunakan untuk menggambar ....", options: ["wajah manusia","sudut bangunan atau gedung","bunga di vas","pemandangan dari atas"], answer: 1, solution: "1. Perspektif dua titik hilang memiliki dua titik lenyap di garis horizon. 2. Teknik ini cocok untuk menggambar objek yang terlihat dari sudutnya. 3. Contohnya menggambar sudut bangunan atau gedung agar tampak tiga dimensi." },
{ q: "Gambar perspektif dengan tiga titik hilang digunakan untuk menggambar objek yang dilihat dari ....", options: ["depan lurus","jarak sangat dekat","samping sejajar mata","atas (pandangan burung) atau bawah"], answer: 3, solution: "1. Perspektif tiga titik hilang menambah satu titik hilang vertikal. 2. Titik tambahan ini untuk garis-garis tegak yang juga tampak menyempit. 3. Teknik ini dipakai untuk pandangan dari atas seperti burung atau dari bawah ke gedung tinggi." },
{ q: "Dalam menggambar tubuh manusia, bagian yang dijadikan patokan ukuran (modul) adalah ....", options: ["lebar pinggul","lebar bahu","tinggi kepala","panjang lengan"], answer: 2, solution: "1. Proporsi tubuh diukur dengan satuan patokan yang disebut modul. 2. Modul yang umum dipakai adalah tinggi kepala. 3. Semua bagian tubuh lain diukur berdasarkan kelipatan tinggi kepala." },
{ q: "Tinggi tubuh orang dewasa yang proporsional adalah sekitar ....", options: ["10 kali tinggi kepalanya","sama dengan tinggi kepalanya","3-4 kali tinggi kepalanya","7-7,5 kali tinggi kepalanya"], answer: 3, solution: "1. Tubuh manusia dewasa memiliki perbandingan ukuran tertentu. 2. Jika tinggi kepala dijadikan satu satuan, tinggi badan sekitar 7 hingga 7,5 satuan. 3. Patokan ini membantu menggambar manusia agar tidak terlihat cebol atau terlalu jangkung." },
{ q: "Gambar ilustrasi berfungsi untuk ....", options: ["menggantikan seluruh isi buku","menjadi sampul tanpa isi","menyembunyikan makna teks","memperjelas atau memperindah isi teks atau buku"], answer: 3, solution: "1. Ilustrasi berasal dari kata illustrate yang artinya menjelaskan. 2. Gambar ilustrasi diletakkan berdampingan dengan teks. 3. Fungsinya memperjelas isi bacaan dan membuat buku lebih menarik." },
{ q: "Ciri khas komik sebagai karya gambar bercerita adalah ....", options: ["tanpa gambar sama sekali","berupa foto asli","gambar berurutan dilengkapi balon kata","hanya terdiri dari satu gambar"], answer: 2, solution: "1. Komik menyampaikan cerita lewat rangkaian gambar. 2. Gambar-gambar disusun berurutan dalam panel-panel. 3. Percakapan tokoh ditulis dalam balon kata sehingga cerita mudah diikuti." },
{ q: "Seseorang melukis untuk menyalurkan perasaan sedihnya. Hal ini menunjukkan fungsi seni sebagai ....", options: ["alat upacara adat","sarana jual beli","media pendidikan","pemenuhan kebutuhan individu"], answer: 3, solution: "1. Seni dapat berfungsi untuk memenuhi kebutuhan batin seseorang. 2. Melukis untuk menyalurkan perasaan adalah wujud ekspresi diri. 3. Fungsi seni untuk kepuasan dan ekspresi pribadi ini disebut fungsi individu." },
{ q: "Topeng dan sesaji yang dibuat untuk upacara adat menunjukkan fungsi seni sebagai ....", options: ["media hiburan","alat komunikasi","sarana pendidikan","sarana ritual"], answer: 3, solution: "1. Sejak zaman dahulu seni dipakai dalam upacara keagamaan dan adat. 2. Topeng, sesaji, dan ukiran dibuat untuk keperluan ritual tersebut. 3. Fungsi seni yang berkaitan dengan upacara dan kepercayaan ini disebut fungsi ritual." },
{ q: "Lukisan dan patung hias termasuk seni murni karena ....", options: ["dibuat hanya untuk dinikmati keindahannya","harganya selalu murah","dibuat dengan mesin","bisa dipakai sehari-hari"], answer: 0, solution: "1. Seni murni (fine art) mengutamakan nilai keindahan. 2. Lukisan dan patung hias dibuat untuk dinikmati keindahannya, bukan untuk dipakai. 3. Berbeda dengan seni terapan yang memiliki fungsi pakai dalam kehidupan sehari-hari." },
{ q: "Vas bunga hias dan ukiran pada mebel termasuk seni terapan karena ....", options: ["memiliki fungsi pakai sekaligus nilai keindahan","dibuat tanpa memperhatikan bentuk","tidak memiliki nilai seni","hanya untuk dipajang tanpa fungsi"], answer: 0, solution: "1. Seni terapan (applied art) menggabungkan keindahan dan kegunaan. 2. Vas bunga bisa dipakai menaruh bunga sekaligus indah dipandang. 3. Karena memiliki fungsi pakai di samping nilai seninya, karya ini disebut seni terapan." },
{ q: "Kerajinan anyaman biasanya dibuat dari bahan ....", options: ["logam dan kaca","bambu dan rotan","batu dan marmer","plastik dan karet"], answer: 1, solution: "1. Anyaman dibuat dengan teknik menyilang-nyilangkan bahan. 2. Bahan yang lentur dan kuat seperti bambu dan rotan cocok untuk dianyam. 3. Hasilnya berupa tikar, keranjang, dan topi." },
{ q: "Gerabah adalah kerajinan yang dibuat dari ....", options: ["kayu yang diukir","logam yang dilelehkan","kain yang ditenun","tanah liat yang dibakar"], answer: 3, solution: "1. Gerabah adalah kerajinan tradisional dari tanah liat. 2. Tanah liat dibentuk menjadi kendi, pot, atau gentong lalu dikeringkan. 3. Setelah itu dibakar agar keras dan tahan lama." },
{ q: "Daerah di Indonesia yang terkenal sebagai pusat kerajinan ukiran kayu adalah ....", options: ["Makassar","Jepara","Bali","Yogyakarta"], answer: 1, solution: "1. Ukiran kayu Indonesia terkenal hingga mancanegara. 2. Jepara di Jawa Tengah adalah daerah yang paling terkenal sebagai pusat ukiran kayu. 3. Ukiran Jepara menghiasi mebel, pintu, dan dinding dengan motif yang rumit dan indah." },
{ q: "Tenun ikat adalah kain yang dibuat dengan cara ....", options: ["menorehkan malam dengan canting","menenun benang yang sudah diikat dan dicelup warna","menyablon motif ke kain","menempelkan potongan kain"], answer: 1, solution: "1. Tenun adalah teknik membuat kain dengan menyilangkan benang. 2. Pada tenun ikat, benang diikat dulu lalu dicelup warna sebelum ditenun. 3. Bagian yang diikat tidak kena warna sehingga membentuk motif saat ditenun." },
{ q: "Songket adalah kain tenun khas yang memiliki ciri ....", options: ["diwarnai dengan teknik celup","motif dicetak dengan stempel","ditenun dengan benang emas atau perak","dibuat dari anyaman bambu"], answer: 2, solution: "1. Songket adalah kain tenun mewah dari Sumatra, misalnya Palembang dan Minangkabau. 2. Ciri khasnya adalah motif yang ditenun memakai benang emas atau perak. 3. Kilau benang emas membuat songket tampak mewah dan dipakai untuk acara adat." },
{ q: "Pada notasi balok, tanda kunci yang diletakkan pada garis kedua paranada dan menunjukkan letak nada G disebut ...", options: ["kunci G","kunci F","kunci C","kunci D"], answer: 0, solution: "1. Kunci G (kunci treble) selalu ditulis pada garis kedua paranada. 2. Bentuknya melingkari garis kedua sehingga garis itu dibaca sebagai nada G. 3. Karena itu jawabannya kunci G." },
{ q: "Kunci F pada notasi balok disebut juga kunci ...", options: ["treble","bass","alto","sopran"], answer: 1, solution: "1. Kunci F menandai letak nada F pada garis keempat paranada. 2. Nada-nada di sekitarnya bernada rendah sehingga cocok untuk suara rendah. 3. Karena dipakai untuk nada-nada rendah, kunci F disebut juga kunci bass." },
{ q: "Nada penuh (whole note) pada notasi balok berbunyi selama ...", options: ["satu ketuk","dua ketuk","empat ketuk","delapan ketuk"], answer: 2, solution: "1. Nada penuh berbentuk bulatan kosong tanpa tangkai. 2. Nilai nada penuh adalah yang paling panjang, yaitu 4 ketuk. 3. Jadi nada penuh berbunyi selama empat ketuk." },
{ q: "Nada setengah (half note) berbunyi selama ...", options: ["satu ketuk","dua ketuk","tiga ketuk","empat ketuk"], answer: 1, solution: "1. Nada setengah berbentuk bulatan kosong bertangkai. 2. Nilainya setengah dari nada penuh (4 ketuk), yaitu 2 ketuk. 3. Jadi nada setengah berbunyi selama dua ketuk." },
{ q: "Nada seperempat (quarter note) berbunyi selama ...", options: ["satu ketuk","dua ketuk","setengah ketuk","empat ketuk"], answer: 0, solution: "1. Nada seperempat berbentuk bulatan hitam bertangkai. 2. Nilainya seperempat dari nada penuh (4 ketuk), yaitu 1 ketuk. 3. Jadi nada seperempat berbunyi selama satu ketuk." },
{ q: "Nada seperdelapan (eighth note) berbunyi selama ...", options: ["satu ketuk","dua ketuk","empat ketuk","setengah ketuk"], answer: 3, solution: "1. Nada seperdelapan berbentuk bulatan hitam bertangkai dengan satu bendera. 2. Nilainya setengah dari nada seperempat (1 ketuk), yaitu setengah ketuk. 3. Jadi nada seperdelapan berbunyi selama setengah ketuk." },
{ q: "Tanda diam yang berbentuk kotak kecil menggantung di bawah garis keempat paranada bernilai ...", options: ["satu ketuk","dua ketuk","empat ketuk","setengah ketuk"], answer: 2, solution: "1. Tanda diam penuh (whole rest) berbentuk kotak kecil yang menggantung di bawah garis keempat. 2. Nilainya sama dengan nada penuh, yaitu 4 ketuk diam. 3. Jadi tanda itu bernilai empat ketuk." },
{ q: "Tanda diam yang berbentuk kotak kecil duduk di atas garis ketiga paranada bernilai ...", options: ["satu ketuk","dua ketuk","empat ketuk","setengah ketuk"], answer: 1, solution: "1. Tanda diam setengah (half rest) berbentuk kotak kecil yang duduk di atas garis ketiga. 2. Nilainya sama dengan nada setengah, yaitu 2 ketuk diam. 3. Jadi tanda itu bernilai dua ketuk." },
{ q: "Tanda diam yang bentuknya mirip huruf Z miring adalah ...", options: ["tanda diam seperempat","tanda diam setengah","tanda diam penuh","tanda diam seperdelapan"], answer: 0, solution: "1. Tanda diam seperempat berbentuk seperti huruf Z yang miring. 2. Nilainya sama dengan nada seperempat, yaitu 1 ketuk diam. 3. Jadi bentuk mirip Z miring itu adalah tanda diam seperempat." },
{ q: "Garis tegak yang membatasi satu birama dengan birama berikutnya disebut ...", options: ["garis paranada","garis bantu","garis melodi","garis birama"], answer: 3, solution: "1. Setiap birama dipisahkan oleh garis tegak. 2. Garis tegak pembatas birama itu disebut garis birama (bar line). 3. Jadi jawabannya garis birama." },
{ q: "Notasi balok dibaca dengan arah ...", options: ["kanan ke kiri","atas ke bawah","kiri ke kanan","bawah ke atas"], answer: 2, solution: "1. Notasi balok ditulis pada paranada yang dibaca berurutan. 2. Seperti membaca tulisan latin, notasi balok dibaca dari kiri ke kanan. 3. Jadi arah bacanya kiri ke kanan." },
{ q: "Ciri tangga nada minor dibandingkan tangga nada mayor adalah ...", options: ["nada ke-3 dan ke-6 dinaikkan setengah laras","nada ke-3 dan ke-6 diturunkan setengah laras","semua nada dinaikkan setengah laras","tidak ada perbedaan dengan mayor"], answer: 1, solution: "1. Tangga nada minor natural dibentuk dari tangga nada mayor. 2. Nada ke-3 dan ke-6 diturunkan setengah laras sehingga terdengar sendu. 3. Jadi cirinya nada ke-3 dan ke-6 diturunkan setengah laras." },
{ q: "Tangga nada A minor natural terdiri atas nada ...", options: ["A-B-C-D-E-F-G-A","A-B-C#-D-E-F#-G#-A","C-D-E-F-G-A-B-C","A-Bb-C-D-E-F-G-A"], answer: 0, solution: "1. Tangga nada A minor natural tidak memakai tanda kres maupun mol. 2. Urutannya A-B-C-D-E-F-G-A. 3. Jadi jawabannya A-B-C-D-E-F-G-A." },
{ q: "Lagu yang bertangga nada minor umumnya memberikan kesan ...", options: ["gembira","semangat","megah","sedih"], answer: 3, solution: "1. Tangga nada minor memiliki interval yang lebih kecil pada nada ke-3. 2. Susunan itu membuat lagu terdengar sendu dan melankolis. 3. Jadi kesan lagu bertangga nada minor adalah sedih." },
{ q: "Tangga nada pentatonis terdiri atas ... nada dalam satu oktaf.", options: ["3 nada","4 nada","5 nada","7 nada"], answer: 2, solution: "1. Kata penta berarti lima. 2. Tangga nada pentatonis hanya memakai lima nada pokok dalam satu oktaf. 3. Jadi jawabannya 5 nada." },
{ q: "Laras slendro pada gamelan Jawa memiliki ciri ...", options: ["tujuh nada dengan jarak berbeda-beda","lima nada dengan jarak interval hampir sama","lima nada seperti mayor","tiga nada minor"], answer: 1, solution: "1. Slendro adalah laras pentatonis gamelan Jawa. 2. Kelima nadanya memiliki jarak interval yang hampir sama rata. 3. Jadi ciri slendro adalah lima nada dengan jarak interval hampir sama." },
{ q: "Laras pelog terdiri atas ... nada.", options: ["7 nada","5 nada","12 nada","3 nada"], answer: 0, solution: "1. Pelog adalah salah satu laras utama gamelan Jawa. 2. Berbeda dengan slendro, pelog memakai tujuh nada. 3. Jadi laras pelog terdiri atas 7 nada." },
{ q: "Dua laras utama yang dipakai dalam gamelan Jawa adalah ...", options: ["mayor dan minor","diatonis dan kromatis","slendro dan pelog","pentatonis dan heksatonis"], answer: 2, solution: "1. Gamelan Jawa tidak memakai tangga nada mayor-minor. 2. Sistem nadanya disebut laras, yaitu slendro dan pelog. 3. Jadi dua laras utama gamelan Jawa adalah slendro dan pelog." },
{ q: "Interval prime adalah jarak antara ...", options: ["dua nada yang sama","dua nada berurutan","nada pertama dan ketiga","nada pertama dan kedelapan"], answer: 0, solution: "1. Prime berasal dari kata prima yang berarti pertama. 2. Interval prime adalah jarak dari suatu nada ke nada yang sama, misalnya C ke C. 3. Jadi prime adalah jarak antara dua nada yang sama." },
{ q: "Interval dari nada C ke E disebut interval ...", options: ["sekon","terts","kuart","kwint"], answer: 1, solution: "1. Hitung urutan nada: C(1)-D(2)-E(3). 2. Jarak C ke E mencakup tiga nada sehingga disebut terts. 3. Jadi interval C ke E adalah terts." },
{ q: "Interval dari nada C ke F disebut interval ...", options: ["terts","kwint","kuart","oktaf"], answer: 2, solution: "1. Hitung urutan nada: C(1)-D(2)-E(3)-F(4). 2. Jarak C ke F mencakup empat nada sehingga disebut kuart. 3. Jadi interval C ke F adalah kuart." },
{ q: "Interval dari nada C ke G disebut interval ...", options: ["terts","kuart","oktaf","kwint"], answer: 3, solution: "1. Hitung urutan nada: C(1)-D(2)-E(3)-F(4)-G(5). 2. Jarak C ke G mencakup lima nada sehingga disebut kwint. 3. Jadi interval C ke G adalah kwint." },
{ q: "Interval dari nada C ke C tinggi (C') disebut interval ...", options: ["oktaf","septim","sekon","terts"], answer: 0, solution: "1. Hitung urutan nada: C(1) sampai C berikutnya (8). 2. Jarak delapan nada itu disebut oktaf. 3. Jadi interval C ke C tinggi adalah oktaf." },
{ q: "Nada G merupakan interval kwint dari nada ...", options: ["D","C","E","F"], answer: 1, solution: "1. Kwint berarti jarak lima nada. 2. Hitung dari C: C(1)-D(2)-E(3)-F(4)-G(5), nada kelimanya adalah G. 3. Jadi G adalah kwint dari nada C." },
{ q: "Akor C mayor tersusun dari nada ...", options: ["C-E-G","C-D-G","C-F-A","D-F-A"], answer: 0, solution: "1. Akor mayor dibentuk dari nada ke-1, ke-3, dan ke-5 tangga nada mayor. 2. Pada tangga nada C mayor: nada ke-1=C, ke-3=E, ke-5=G. 3. Jadi akor C mayor tersusun dari nada C-E-G." },
{ q: "Akor yang terdiri atas tiga nada disebut akor ...", options: ["dwinada","catur nada","trinada","panca nada"], answer: 2, solution: "1. Tri berarti tiga. 2. Akor yang tersusun dari tiga nada, misalnya C-E-G, disebut akor trinada (triad). 3. Jadi jawabannya trinada." },
{ q: "Akor C minor tersusun dari nada ...", options: ["C-E-G","C-D-G","C-F-Ab","C-Es-G"], answer: 3, solution: "1. Akor minor dibentuk dengan menurunkan nada ke-3 akor mayor setengah laras. 2. Akor C mayor C-E-G menjadi C-Es-G untuk C minor. 3. Jadi akor C minor tersusun dari nada C-Es-G." },
{ q: "Dalam sebuah lagu, akor berfungsi untuk ...", options: ["menggantikan melodi","mengiringi melodi","menghapus melodi","mempercepat melodi"], answer: 1, solution: "1. Akor adalah gabungan tiga nada atau lebih yang dibunyikan bersama. 2. Rangkaian akor menjadi harmoni yang mengiringi jalannya melodi. 3. Jadi fungsi akor adalah mengiringi melodi." },
{ q: "Tanda tempo yang berarti sangat lambat adalah ...", options: ["largo","vivace","presto","moderato"], answer: 0, solution: "1. Tanda tempo menunjukkan cepat lambatnya lagu. 2. Largo berarti dimainkan sangat lambat dan khidmat. 3. Jadi tanda tempo yang berarti sangat lambat adalah largo." },
{ q: "Tanda tempo yang berarti sedang seperti langkah orang berjalan adalah ...", options: ["largo","andante","presto","vivace"], answer: 1, solution: "1. Andante berasal dari kata andare yang berarti berjalan. 2. Tempo andante dimainkan sedang, seperti kecepatan langkah orang berjalan. 3. Jadi jawabannya andante." },
{ q: "Tanda tempo yang berarti sedang adalah ...", options: ["largo","vivace","moderato","presto"], answer: 2, solution: "1. Moderato berasal dari kata moderate yang berarti sedang. 2. Tempo moderato tidak lambat dan tidak cepat. 3. Jadi tanda tempo yang berarti sedang adalah moderato." },
{ q: "Tanda tempo yang berarti cepat dan hidup adalah ...", options: ["largo","andante","moderato","vivace"], answer: 3, solution: "1. Vivace berasal dari kata vivo yang berarti hidup. 2. Tempo vivace dimainkan cepat dengan penuh semangat dan hidup. 3. Jadi tanda tempo yang berarti cepat dan hidup adalah vivace." },
{ q: "Tanda tempo yang berarti sangat cepat adalah ...", options: ["presto","largo","andante","moderato"], answer: 0, solution: "1. Presto adalah tanda tempo untuk kecepatan tinggi. 2. Lagu bertempo presto dimainkan sangat cepat. 3. Jadi tanda tempo yang berarti sangat cepat adalah presto." },
{ q: "Tanda dinamika p (piano) berarti dimainkan dengan suara ...", options: ["keras","lembut","makin keras","makin lembut"], answer: 1, solution: "1. Dinamika mengatur keras lembutnya bunyi. 2. Tanda p (piano) berarti dimainkan lembut. 3. Jadi piano berarti suara lembut." },
{ q: "Tanda dinamika f (forte) berarti dimainkan dengan suara ...", options: ["lembut","makin lembut","keras","makin keras"], answer: 2, solution: "1. Tanda f adalah singkatan dari forte. 2. Forte berarti dimainkan dengan suara keras dan kuat. 3. Jadi forte berarti suara keras." },
{ q: "Tanda < (crescendo) berarti suara dimainkan ...", options: ["makin lembut","lembut","keras","makin keras"], answer: 3, solution: "1. Tanda < membuka ke arah kanan seperti suara yang membesar. 2. Crescendo berarti volume suara bertambah, makin keras. 3. Jadi tanda < berarti makin keras." },
{ q: "Tanda > (decrescendo) berarti suara dimainkan ...", options: ["makin lembut","makin keras","keras","lembut"], answer: 0, solution: "1. Tanda > mengecil ke arah kanan seperti suara yang mengecil. 2. Decrescendo berarti volume suara berkurang, makin lembut. 3. Jadi tanda > berarti makin lembut." },
{ q: "Tanda dinamika mf (mezzo forte) berarti dimainkan ...", options: ["sangat lembut","sangat keras","agak keras","agak lembut"], answer: 2, solution: "1. Mezzo berarti setengah atau agak. 2. Mezzo forte berarti setingkat di bawah forte, yaitu agak keras. 3. Jadi mf berarti agak keras." },
{ q: "Lagu dengan birama 4/4 memiliki ... ketukan dalam satu birama.", options: ["2 ketuk","4 ketuk","3 ketuk","6 ketuk"], answer: 1, solution: "1. Angka atas pada tanda birama menunjukkan jumlah ketukan. 2. Pada birama 4/4, angka atasnya 4 sehingga ada 4 ketuk per birama. 3. Jadi lagu birama 4/4 memiliki 4 ketukan." },
{ q: "Lagu dengan birama 3/4 memiliki ... ketukan dalam satu birama.", options: ["2 ketuk","4 ketuk","3 ketuk","6 ketuk"], answer: 2, solution: "1. Angka atas pada tanda birama menunjukkan jumlah ketukan. 2. Pada birama 3/4, angka atasnya 3 sehingga ada 3 ketuk per birama. 3. Jadi lagu birama 3/4 memiliki 3 ketukan." },
{ q: "Lagu dengan birama 2/4 memiliki ... ketukan dalam satu birama.", options: ["2 ketuk","3 ketuk","4 ketuk","6 ketuk"], answer: 0, solution: "1. Angka atas pada tanda birama menunjukkan jumlah ketukan. 2. Pada birama 2/4, angka atasnya 2 sehingga ada 2 ketuk per birama. 3. Jadi lagu birama 2/4 memiliki 2 ketukan." },
{ q: "Pada birama 6/8, jumlah ketukan dalam satu birama adalah ...", options: ["2 ketuk","3 ketuk","4 ketuk","6 ketuk"], answer: 3, solution: "1. Angka atas birama 6/8 adalah 6. 2. Artinya ada 6 ketuk per birama dengan nada seperdelapan bernilai satu ketuk. 3. Jadi birama 6/8 memiliki 6 ketukan." },
{ q: "Pada tanda birama 3/4, angka 3 menunjukkan ...", options: ["jenis nada yang dipakai","jumlah ketukan dalam satu birama","kecepatan lagu","keras lembut lagu"], answer: 1, solution: "1. Tanda birama terdiri atas dua angka. 2. Angka atas menunjukkan jumlah ketukan dalam satu birama. 3. Jadi angka 3 berarti tiga ketukan per birama." },
{ q: "Suling dan serunai termasuk alat musik ...", options: ["membranofon","idiofon","aerofon","kordofon"], answer: 2, solution: "1. Suling dan serunai dibunyikan dengan cara ditiup. 2. Alat musik yang sumber bunyinya getaran udara disebut aerofon. 3. Jadi suling dan serunai termasuk aerofon." },
{ q: "Gendang dan rebana termasuk alat musik ...", options: ["membranofon","aerofon","idiofon","kordofon"], answer: 0, solution: "1. Gendang dan rebana dibunyikan dengan memukul selaput kulit. 2. Alat musik yang sumber bunyinya getaran selaput (membran) disebut membranofon. 3. Jadi gendang dan rebana termasuk membranofon." },
{ q: "Gong, saron, dan bonang termasuk alat musik ...", options: ["aerofon","idiofon","membranofon","kordofon"], answer: 1, solution: "1. Gong, saron, dan bonang dibunyikan dengan dipukul. 2. Sumber bunyinya adalah getaran badan alat itu sendiri, disebut idiofon. 3. Jadi ketiganya termasuk idiofon." },
{ q: "Rebab, kecapi, dan gambus termasuk alat musik ...", options: ["aerofon","membranofon","idiofon","kordofon"], answer: 3, solution: "1. Rebab, kecapi, dan gambus memakai dawai atau senar. 2. Alat musik yang sumber bunyinya getaran dawai disebut kordofon. 3. Jadi ketiganya termasuk kordofon." },
{ q: "Gendang menghasilkan bunyi dari getaran ...", options: ["selaput kulit yang dipukul","senar yang dipetik","udara yang ditiup","badan logam yang dipukul"], answer: 0, solution: "1. Gendang berbentuk tabung dengan selaput kulit di sisinya. 2. Saat selaput kulit dipukul, ia bergetar dan menghasilkan bunyi. 3. Jadi bunyi gendang berasal dari getaran selaput kulit yang dipukul." },
{ q: "Saron dan bonang dimainkan dengan cara ...", options: ["dipetik","ditiup","dipukul","digesek"], answer: 2, solution: "1. Saron dan bonang terbuat dari bilah logam. 2. Keduanya dibunyikan dengan dipukul memakai tabuh kayu. 3. Jadi saron dan bonang dimainkan dengan cara dipukul." },
{ q: "Serunai adalah alat musik tiup tradisional yang berasal dari ...", options: ["Jawa","Minangkabau","Bali","Betawi"], answer: 1, solution: "1. Serunai adalah alat musik tiup berlidah ganda. 2. Serunai berasal dari daerah Minangkabau, Sumatera Barat. 3. Jadi serunai berasal dari Minangkabau." },
{ q: "Gamelan adalah seperangkat alat musik tradisional yang berasal dari ...", options: ["Jawa","Sumatera","Kalimantan","Sulawesi"], answer: 0, solution: "1. Gamelan terdiri atas gong, saron, bonang, kenong, dan gendang. 2. Perangkat musik ini lahir dan berkembang di tanah Jawa. 3. Jadi gamelan berasal dari Jawa." },
{ q: "Gamelan khas Bali yang dimainkan cepat, dinamis, dan penuh semangat disebut gamelan ...", options: ["gamelan degung","gamelan sekati","gamelan slendro","gamelan gong kebyar"], answer: 3, solution: "1. Bali memiliki jenis gamelan yang berbeda dengan Jawa. 2. Gamelan gong kebyar dimainkan cepat, dinamis, dan penuh ledakan semangat. 3. Jadi jawabannya gamelan gong kebyar." },
{ q: "Dalam gamelan Jawa, alat musik yang menjadi penanda akhir sebuah gongan adalah ...", options: ["saron","gong","bonang","kenong"], answer: 1, solution: "1. Satu gongan adalah satu putaran pola gending. 2. Akhir gongan ditandai dengan pukulan gong yang besar dan bergema. 3. Jadi penanda akhir gongan adalah gong." },
{ q: "Gamelan pada umumnya dimainkan secara ...", options: ["sendiri-sendiri","bergantian solo","bersama-sama","tanpa iringan"], answer: 2, solution: "1. Gamelan terdiri atas banyak alat musik yang berbeda peran. 2. Semua pemain membunyikan alatnya secara bersamaan mengikuti pola gending. 3. Jadi gamelan dimainkan secara bersama-sama." },
{ q: "Pencipta lagu wajib nasional Indonesia Raya adalah ...", options: ["W.R. Supratman","Ismail Marzuki","Ibu Sud","Husein Mutahar"], answer: 0, solution: "1. Indonesia Raya adalah lagu kebangsaan Indonesia. 2. Lagu ini diciptakan oleh Wage Rudolf Supratman pada tahun 1928. 3. Jadi penciptanya adalah W.R. Supratman." },
{ q: "Pencipta lagu Garuda Pancasila adalah ...", options: ["Ismail Marzuki","Sudharnoto","Cornel Simanjuntak","R. Kusbini"], answer: 1, solution: "1. Lagu Garuda Pancasila sering dinyanyikan dalam upacara. 2. Lagu ini diciptakan oleh Sudharnoto. 3. Jadi penciptanya adalah Sudharnoto." },
{ q: "Pencipta lagu Maju Tak Gentar adalah ...", options: ["Ibu Sud","L. Manik","Cornel Simanjuntak","W.R. Supratman"], answer: 2, solution: "1. Lagu Maju Tak Gentar membangkitkan semangat perjuangan. 2. Lagu ini diciptakan oleh Cornel Simanjuntak. 3. Jadi penciptanya adalah Cornel Simanjuntak." },
{ q: "Pencipta lagu Halo-Halo Bandung adalah ...", options: ["Sudharnoto","Husein Mutahar","Ibu Sud","Ismail Marzuki"], answer: 3, solution: "1. Lagu Halo-Halo Bandung berkisah tentang perjuangan di Bandung. 2. Lagu ini diciptakan oleh Ismail Marzuki. 3. Jadi penciptanya adalah Ismail Marzuki." },
{ q: "Pencipta lagu Berkibarlah Benderaku adalah ...", options: ["Ibu Sud","R. Soeharto","L. Manik","Kusbini"], answer: 0, solution: "1. Lagu Berkibarlah Benderaku bertema bendera merah putih. 2. Lagu ini diciptakan oleh Ibu Sud. 3. Jadi penciptanya adalah Ibu Sud." },
{ q: "Pencipta lagu Satu Nusa Satu Bangsa adalah ...", options: ["W.R. Supratman","L. Manik","Ismail Marzuki","Sudharnoto"], answer: 1, solution: "1. Lagu Satu Nusa Satu Bangsa bertema persatuan Indonesia. 2. Lagu ini diciptakan oleh Liberty Manik (L. Manik). 3. Jadi penciptanya adalah L. Manik." },
{ q: "Pencipta lagu Hari Merdeka (17 Agustus) adalah ...", options: ["Cornel Simanjuntak","R. Kusbini","Husein Mutahar","Ibu Sud"], answer: 2, solution: "1. Lagu Hari Merdeka dinyanyikan setiap peringatan 17 Agustus. 2. Lagu ini diciptakan oleh Husein Mutahar. 3. Jadi penciptanya adalah Husein Mutahar." },
{ q: "Pencipta lagu Bagimu Negeri adalah ...", options: ["L. Manik","Husein Mutahar","R. Soeharto","R. Kusbini"], answer: 3, solution: "1. Lagu Bagimu Negeri berisi janji bakti untuk negeri. 2. Lagu ini diciptakan oleh R. Kusbini (Kusbini). 3. Jadi penciptanya adalah R. Kusbini." },
{ q: "Pencipta lagu Dari Sabang Sampai Merauke adalah ...", options: ["R. Soeharto","Ismail Marzuki","Sudharnoto","Cornel Simanjuntak"], answer: 0, solution: "1. Lagu Dari Sabang Sampai Merauke menggambarkan luasnya Indonesia. 2. Lagu ini diciptakan oleh R. Soeharto. 3. Jadi penciptanya adalah R. Soeharto." },
{ q: "Lagu daerah Soleram berasal dari ...", options: ["Jambi","Riau","Sumatera Barat","Sumatera Selatan"], answer: 1, solution: "1. Soleram adalah lagu daerah tentang anak. 2. Lagu ini berasal dari provinsi Riau. 3. Jadi Soleram berasal dari Riau." },
{ q: "Lagu daerah Bubuy Bulan berasal dari ...", options: ["Jawa Timur","Jawa Tengah","Jawa Barat","Banten"], answer: 2, solution: "1. Bubuy Bulan adalah lagu daerah berbahasa Sunda. 2. Lagu ini berasal dari Jawa Barat. 3. Jadi Bubuy Bulan berasal dari Jawa Barat." },
{ q: "Lagu daerah Cublak-cublak Suweng berasal dari ...", options: ["Jawa Timur","Jawa Barat","Jawa Tengah","DI Yogyakarta"], answer: 0, solution: "1. Cublak-cublak Suweng adalah lagu dolanan anak. 2. Lagu ini berasal dari Jawa Timur. 3. Jadi Cublak-cublak Suweng berasal dari Jawa Timur." },
{ q: "Lagu daerah Rasa Sayange berasal dari ...", options: ["Papua","NTT","Sulawesi Utara","Maluku"], answer: 3, solution: "1. Rasa Sayange adalah lagu tentang persaudaraan. 2. Lagu ini berasal dari Maluku. 3. Jadi Rasa Sayange berasal dari Maluku." },
{ q: "Lagu daerah Bungong Jeumpa berasal dari ...", options: ["Sumatera Utara","Aceh","Sumatera Barat","Riau"], answer: 1, solution: "1. Bungong Jeumpa berarti bunga cempaka dalam bahasa Aceh. 2. Lagu ini berasal dari Aceh. 3. Jadi Bungong Jeumpa berasal dari Aceh." },
{ q: "Lagu daerah Manuk Dadali berasal dari ...", options: ["Jawa Tengah","Jawa Timur","Jawa Barat","Banten"], answer: 2, solution: "1. Manuk Dadali berarti burung garuda dalam bahasa Sunda. 2. Lagu ini berasal dari Jawa Barat. 3. Jadi Manuk Dadali berasal dari Jawa Barat." },
{ q: "Lagu daerah Sajojo berasal dari ...", options: ["Papua","Maluku","NTT","Sulawesi Utara"], answer: 0, solution: "1. Sajojo adalah lagu ceria dengan gerakan khas. 2. Lagu ini berasal dari Papua. 3. Jadi Sajojo berasal dari Papua." },
{ q: "Lagu daerah Jali-jali berasal dari ...", options: ["Jawa Barat","Jawa Tengah","Banten","Jakarta"], answer: 3, solution: "1. Jali-jali adalah lagu Betawi tentang buah jali. 2. Lagu ini berasal dari Betawi, Jakarta. 3. Jadi Jali-jali berasal dari Jakarta." },
{ q: "Lagu daerah Paris Barantai berasal dari ...", options: ["Kalimantan Timur","Kalimantan Selatan","Kalimantan Barat","Kalimantan Tengah"], answer: 1, solution: "1. Paris Barantai adalah lagu berbahasa Banjar. 2. Lagu ini berasal dari Kalimantan Selatan. 3. Jadi Paris Barantai berasal dari Kalimantan Selatan." },
{ q: "Unsur utama dalam seni tari adalah ...", options: ["gerak","kostum","properti","panggung"], answer: 0, solution: "1. Tari adalah seni yang diungkapkan melalui tubuh. 2. Tanpa gerak tubuh tidak ada tarian, sedangkan kostum dan panggung hanya pendukung. 3. Jadi unsur utama tari adalah gerak." },
{ q: "Fungsi iringan dalam sebuah tarian adalah ...", options: ["menggantikan gerak","menjadi tontonan utama","mengiringi dan mengatur ritme gerak","menghapus suara penonton"], answer: 2, solution: "1. Iringan tari bisa berupa musik atau bunyi-bunyian. 2. Iringan memberi tempo dan ritme agar gerak penari kompak. 3. Jadi fungsi iringan adalah mengiringi dan mengatur ritme gerak." },
{ q: "Tari yang tumbuh dan berkembang secara turun-temurun di kalangan masyarakat umum disebut tari ...", options: ["tari klasik","tari rakyat","tari kreasi","tari kontemporer"], answer: 1, solution: "1. Tari rakyat lahir dari kehidupan masyarakat biasa. 2. Gerakannya sederhana dan diwariskan turun-temurun. 3. Jadi tari yang tumbuh di kalangan masyarakat umum disebut tari rakyat." },
{ q: "Ciri utama tari klasik adalah ...", options: ["bebas tanpa aturan","diciptakan baru","untuk ritual saja","memiliki kaidah baku dan lahir di lingkungan istana"], answer: 3, solution: "1. Tari klasik berkembang di lingkungan keraton atau istana. 2. Gerakannya terikat kaidah dan pakem yang baku. 3. Jadi cirinya memiliki kaidah baku dan lahir di lingkungan istana." },
{ q: "Tari yang ditarikan oleh satu orang penari disebut tari ...", options: ["tunggal","berpasangan","kelompok","massal"], answer: 0, solution: "1. Jumlah penari menentukan jenis penyajian tari. 2. Tari yang dibawakan hanya oleh satu orang disebut tari tunggal. 3. Jadi jawabannya tari tunggal." },
{ q: "Pola lantai yang membentuk garis lurus ke depan, ke samping, atau diagonal disebut pola lantai ...", options: ["melingkar","zigzag","lurus","lengkung"], answer: 2, solution: "1. Pola lantai adalah garis yang dilalui penari di panggung. 2. Jika garisnya lurus ke depan, samping, atau diagonal, disebut pola lantai lurus. 3. Jadi jawabannya pola lantai lurus." },
{ q: "Pola lantai yang membentuk garis patah-patah seperti huruf Z disebut pola lantai ...", options: ["lurus","zigzag","melingkar","lengkung"], answer: 1, solution: "1. Pola lantai zigzag membentuk garis berbelok-belok tajam. 2. Bentuknya seperti huruf Z yang berulang. 3. Jadi pola lantai itu disebut zigzag." },
{ q: "Pola lantai yang membentuk setengah lingkaran disebut pola lantai ...", options: ["lurus","zigzag","melingkar","lengkung"], answer: 3, solution: "1. Pola lantai lengkung membentuk garis melengkung. 2. Bentuknya seperti setengah lingkaran atau busur. 3. Jadi pola lantai itu disebut lengkung." },
{ q: "Gerak tari yang tidak mengandung arti khusus dan hanya menonjolkan keindahan disebut gerak ...", options: ["gerak murni","gerak tari","gerak bebas","gerak lantai"], answer: 0, solution: "1. Gerak tari ada yang bermakna dan ada yang tidak. 2. Gerak yang tidak mengandung arti khusus dan hanya menonjolkan keindahan disebut gerak murni. 3. Jadi jawabannya gerak murni." },
{ q: "Gerak tari yang dilakukan dengan posisi jongkok atau duduk termasuk level ...", options: ["tinggi","sedang","rendah","melayang"], answer: 2, solution: "1. Level gerak menunjukkan tinggi rendahnya posisi tubuh. 2. Posisi jongkok atau duduk berada dekat lantai sehingga termasuk level rendah. 3. Jadi jawabannya level rendah." },
{ q: "Tari Sigeh Penguten yang berfungsi menyambut tamu berasal dari ...", options: ["Papua","Lampung","Bali","Jawa Timur"], answer: 1, solution: "1. Tari Sigeh Penguten dibawakan untuk menyambut tamu kehormatan. 2. Tarian ini berasal dari provinsi Lampung. 3. Jadi Sigeh Penguten berasal dari Lampung." },
{ q: "Tari Legong berasal dari ...", options: ["Jawa","Sumatera","Sulawesi","Bali"], answer: 3, solution: "1. Tari Legong ditarikan oleh penari putri dengan gerakan gemulai. 2. Tarian ini berasal dari Bali. 3. Jadi Tari Legong berasal dari Bali." },
{ q: "Reog Ponorogo berasal dari ...", options: ["Jawa Timur","Jawa Barat","Jawa Tengah","Banten"], answer: 0, solution: "1. Reog Ponorogo terkenal dengan topeng dadak merak yang besar. 2. Kesenian ini berasal dari Ponorogo, Jawa Timur. 3. Jadi Reog Ponorogo berasal dari Jawa Timur." },
{ q: "Bagian pembuka sebuah pementasan teater yang berisi pengantar cerita disebut ...", options: ["penutup cerita","prolog","puncak konflik","penyelesaian"], answer: 1, solution: "1. Setiap pementasan teater diawali pengantar cerita. 2. Bagian pembuka yang berisi pengantar cerita disebut prolog. 3. Jadi jawabannya prolog." },
{ q: "Bagian penutup sebuah pementasan teater disebut ...", options: ["pembuka","puncak konflik","epilog","dialog samping"], answer: 2, solution: "1. Pementasan teater diakhiri dengan bagian penutup. 2. Bagian penutup yang berisi kesimpulan atau pesan cerita disebut epilog. 3. Jadi jawabannya epilog." },
{ q: "Tokoh yang menjadi lawan atau penentang tokoh utama (protagonis) disebut tokoh ...", options: ["antagonis","protagonis","figuran","pemeran pembantu"], answer: 0, solution: "1. Dalam cerita ada tokoh utama yang disebut protagonis. 2. Tokoh yang menentang atau menjadi lawan protagonis disebut antagonis. 3. Jadi jawabannya antagonis." },
{ q: "Puncak ketegangan atau konflik dalam sebuah lakon disebut ...", options: ["awal cerita","pengenalan tokoh","penyelesaian","klimaks"], answer: 3, solution: "1. Alur cerita bergerak dari pengenalan menuju konflik. 2. Titik konflik yang paling tegang disebut klimaks atau puncak cerita. 3. Jadi jawabannya klimaks." },
{ q: "Latihan terakhir yang dilakukan secara menyeluruh sebelum pementasan disebut ...", options: ["latihan pertama","gladi resik","pemilihan pemain","pembacaan naskah"], answer: 1, solution: "1. Sebelum pentas, pemain berlatih beberapa kali. 2. Latihan terakhir yang menyeluruh seperti pementasan sebenarnya disebut gladi resik. 3. Jadi jawabannya gladi resik." },
{ q: "Tokoh pantomim dunia yang terkenal dengan karakter Bip adalah ...", options: ["Charlie Chaplin","William Shakespeare","Marcel Marceau","Stanislavski"], answer: 2, solution: "1. Pantomim adalah teater tanpa dialog yang mengandalkan gerak tubuh. 2. Marcel Marceau adalah maestro pantomim dunia asal Prancis dengan karakter Bip. 3. Jadi jawabannya Marcel Marceau." },
{ q: "Ciri utama teater opera adalah ...", options: ["seluruh dialog dinyanyikan","tanpa dialog sama sekali","dialog dibisikkan","dialog dibacakan"], answer: 0, solution: "1. Opera menggabungkan drama dan musik. 2. Dalam opera seluruh dialog dan cerita disampaikan dengan nyanyian. 3. Jadi ciri utama opera adalah seluruh dialog dinyanyikan." },
{ q: "Bentuk panggung yang penontonnya hanya menyaksikan dari satu arah (depan) disebut panggung ...", options: ["arena","tapal kuda","amfiteater","proscenium"], answer: 3, solution: "1. Bentuk panggung menentukan posisi penonton. 2. Panggung proscenium dibatasi bingkai sehingga penonton hanya dari arah depan. 3. Jadi jawabannya panggung proscenium." },
{ q: "Lampu panggung yang sorotannya difokuskan pada satu titik disebut ...", options: ["footlight","spotlight","backlight","floodlight"], answer: 1, solution: "1. Tata cahaya memakai berbagai jenis lampu. 2. Lampu yang sorotannya terfokus pada satu titik atau satu pemain disebut spotlight. 3. Jadi jawabannya spotlight." },
{ q: "Wayang orang adalah teater tradisional yang berasal dari ...", options: ["Sumatera","Bali","Jawa","Kalimantan"], answer: 2, solution: "1. Wayang orang membawakan cerita wayang dengan pemain manusia. 2. Kesenian ini lahir dan berkembang di tanah Jawa. 3. Jadi wayang orang berasal dari Jawa." }
  ]
};
